// Generated by scripts/content-index.ts. Starter files a playbook writes into a folder on request, such as
// `o11 ostack launch-videos new`. Edit the files under content/playbooks/<id>/kit/, then regenerate.
export const KITS: Readonly<Record<string, string>> = {
  "playbooks/launch-videos/kit/README.md": "# Launch video\n\nMade with ostack's launch-videos playbook: a launch film, a reel or a product demo. Every frame is a pure function of\ntime: `page/` draws one complete frame for any second (footage or product UI, glass, headlines, end card), headless Chrome captures each frame, and ffmpeg\nencodes them with the mix. One timeline (`edit/timeline.js`) drives the picture, the sound and the audits.\n\nNothing in `media/` or `output/` is committed.\n\n## Layout\n\n```\nedit/        what the video is (edit these)\n  brand.js     name, mark, font, call to action, background, canvas size\n  timeline.js  shots, headlines, narration, music\n  scenes.js    glass components on each shot's open side\n  capture.js   product UI states to capture (product demos)\n  speech.js    spoken phrase timings (written by scripts/speech.mjs)\ncore/        timeline placement and easing, shared by the page and the scripts\npage/        draws one frame: frame.js, headlines.js, overlays.js, ui-shot.js, end-card.js, primitives.js, styles.css\nscripts/     prepare, pauses, capture, speech, sound-effects, mix, render, encode;\n             audit/ stillness, overlap, torn-frames, sound, words\nmedia/       your source files: clips/, narration/, words/, brand/, music.wav, auth.json\noutput/      everything generated\n```\n\n## Setup\n\n```bash\nbun install        # or npm install: just playwright-core\n```\n\nYou also need ffmpeg on your PATH (or `FFMPEG=<path>`) and Google Chrome (or `CHROME=<path>`).\n\n## Make it\n\n```bash\nnode scripts/pauses.mjs <clip>           # where a clip may be cut (reels)\nnode scripts/prepare.mjs --scale 0.5     # footage frames, clip audio, a reel's head line\nnode scripts/capture.mjs                 # product UI states (product demo)\nnode scripts/speech.mjs                  # phrase timings from media/words/\nnode scripts/sound-effects.mjs\nnode scripts/mix.mjs\nnode scripts/render.mjs --scale 0.5      # review size; --from/--to re-render part\nnode scripts/encode.mjs --scale 0.5      # output/video-0.5x.mp4\n```\n\nRender the full size (`--scale 1`, or `2` for 4K from a 1920×1080 layout) only when the user approves the review cut.\n\n## Audit before anyone sees it\n\n| Check | Command | Pass |\n| --- | --- | --- |\n| Nothing jitters | `node scripts/audit/stillness.mjs` | 0 moving |\n| Layout | `node scripts/audit/overlap.mjs` | 0 layout problems |\n| Frames | `node scripts/audit/torn-frames.mjs --video <file>` | every frame, 0 torn |\n| Sound | `node scripts/audit/sound.mjs` | −16 LUFS, peak ≤ −1.5 dBFS, left = right |\n| Words (videos with cuts) | `node scripts/audit/words.mjs` | every kept word heard |\n\nThen look: one frame per second as a contact sheet, and full-size crops of every glass component over its real footage.\n",
  "playbooks/launch-videos/kit/core/motion.js": "// Easing and timing. Every value on screen is a pure function of time, so any frame renders the same on any page.\nexport const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));\nexport const lerp = (a, b, k) => a + (b - a) * k;\nexport const outCubic = (k) => 1 - (1 - k) ** 3;\nexport const outQuint = (k) => 1 - (1 - k) ** 5;\nexport const expoOut = (k) => (k >= 1 ? 1 : 1 - 2 ** (-9 * k));\n// Progress of a tween that starts at `a` and lasts `d` seconds.\nexport const p = (t, a, d, curve = outCubic) => curve(clamp((t - a) / d));\n\n// CSS-style cubic-bezier, solved numerically, so motion uses the same curves as design tools.\nexport function bezier(x1, y1, x2, y2) {\n  const cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx;\n  const cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;\n  const x = (u) => ((ax * u + bx) * u + cx) * u, y = (u) => ((ay * u + by) * u + cy) * u;\n  const dx = (u) => (3 * ax * u + 2 * bx) * u + cx;\n  return (k) => {\n    if (k <= 0) return 0;\n    if (k >= 1) return 1;\n    let u = k;\n    for (let i = 0; i < 8; i++) { const e = x(u) - k, d = dx(u); if (Math.abs(e) < 1e-6 || Math.abs(d) < 1e-6) break; u -= e / d; }\n    return y(clamp(u));\n  };\n}\n// A long deceleration with no overshoot (springs read as cheap), and a smooth in-out for exits and camera moves.\nexport const glide = bezier(0.16, 1, 0.3, 1);\nexport const ease = bezier(0.65, 0, 0.35, 1);\n// Numbers that look random but are the same on every frame and every renderer page.\nexport const rand = (seed) => { const x = Math.sin(seed * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };\n// The one transform every moving layer uses: perspective() keeps Chrome moving it smoothly instead of snapping to\n// whole pixels, and a layer at rest keeps the same compositing path, so it never pops when it lands.\nexport const move = (x = 0, y = 0, scale = 1) =>\n  `perspective(100px) translate3d(${x.toFixed(3)}px, ${y.toFixed(3)}px, 0)${scale === 1 ? \"\" : ` scale(${scale.toFixed(5)})`}`;\n",
  "playbooks/launch-videos/kit/core/timeline.js": "// Turns edit/timeline.js into output times. One timeline drives the picture, the mix, the sound effects and the\n// audits, so nothing can drift.\n//\n// Times in edit/ are written on each shot's own clock: for a clip, seconds in the source file (the clock its\n// transcript uses); for a UI shot or the end card, seconds from the start of the shot. A clip may keep only some of\n// its source (`keep: [[from, to], ...]`, light cuts for a reel); a time inside a removed stretch lands exactly on the\n// cut, so a headline that ends and the next that starts in a removed pause change at the cut and nothing jumps.\nexport function build({ canvas = { width: 1920, height: 1080 }, fps = 30, layout = \"side\", shots, headlines = [], narration = [], music = null }) {\n  const ids = new Set();\n  const frames = (seconds) => Math.round(seconds * fps);\n  let at = 0;\n  const SHOTS = shots.map((shot) => {\n    if (!shot.id || ids.has(shot.id)) throw new Error(`Every shot needs its own id (${shot.id ?? \"missing\"})`);\n    ids.add(shot.id);\n    const sourced = shot.kind === \"clip\" || (shot.kind === \"end\" && shot.file && shot.to != null);\n    const keep = sourced ? shot.keep ?? [[shot.from ?? 0, shot.to]] : null;\n    if (keep && keep.some(([a, b]) => !(b > a))) throw new Error(`Shot \"${shot.id}\" needs from and to (or keep ranges), in source seconds`);\n    // Each kept range is a whole number of output frames, so picture and sound cut on the same frame.\n    const ranges = keep?.map(([a, b]) => ({ from: a, to: b, frames: frames(b - a) }));\n    const len = ranges ? ranges.reduce((n, r) => n + r.frames, 0) / fps : shot.len;\n    if (!(len > 0)) throw new Error(`Shot \"${shot.id}\" needs ${shot.kind === \"clip\" ? \"from and to\" : \"len\"} (seconds)`);\n    const placed = { ...shot, from: keep?.[0]?.[0] ?? 0, len, at, end: at + len, ranges };\n    at += len;\n    return placed;\n  });\n  const SHOT = Object.fromEntries(SHOTS.map((shot) => [shot.id, shot]));\n  const TOTAL = at;\n  // 99 means \"to the last frame\": a headline or card that never leaves.\n  const HOLD = TOTAL + 1;\n  /** A time on a shot's clock, in output seconds. */\n  const place = (id, t) => {\n    const shot = SHOT[id];\n    if (!shot) throw new Error(`No shot \"${id}\"`);\n    if (t >= 99) return HOLD;\n    if (!shot.ranges) return shot.at + t;\n    let out = 0;\n    for (const [i, r] of shot.ranges.entries()) {\n      // Before the first kept range it extrapolates, so a hook can start a beat before the first frame.\n      if (t < r.from) return shot.at + (i === 0 ? t - r.from : out);\n      if (t < r.to) return shot.at + out + Math.min(t - r.from, r.frames / fps);\n      out += r.frames / fps;\n    }\n    return shot.at + out + (t - shot.ranges.at(-1).to);\n  };\n  /** Whether a source time on a clip survives its cuts. */\n  const kept = (id, t) => SHOT[id]?.ranges?.some((r) => t >= r.from && t < r.from + r.frames / fps) ?? true;\n  // [shot, start, end, side, \"line one|line two\", { hook, logo }]: short paraphrases of what is said.\n  const HEADLINES = headlines.map(([id, start, end, side, text, options = {}]) => ({\n    at: place(id, start), end: place(id, end), side, lines: text.split(\"|\"), hook: Boolean(options.hook), logo: options.logo ?? null,\n  }));\n  // [shot, start, file]: narration in media/narration/<file>.wav, with word timings in media/words/<file>.json.\n  const NARRATION = narration.map(([id, start, file]) => ({ at: place(id, start), file }));\n  const shotAt = (t) => {\n    for (let i = SHOTS.length - 1; i >= 0; i--) if (t >= SHOTS[i].at - 1e-9) return SHOTS[i];\n    return SHOTS[0];\n  };\n  // Every cut: between shots and inside a clip's kept ranges (jump cuts).\n  const CUTS = SHOTS.flatMap((shot, i) => {\n    const inside = [];\n    let out = shot.at;\n    for (const r of (shot.ranges ?? []).slice(0, -1)) { out += r.frames / fps; inside.push(out); }\n    return [...(i > 0 ? [shot.at] : []), ...inside];\n  });\n  return {\n    WIDTH: canvas.width, HEIGHT: canvas.height, FPS: fps, FRAMES: frames(TOTAL), TOTAL, LAYOUT: layout,\n    SHOTS, SHOT, HEADLINES, NARRATION, MUSIC: music, CUTS, place, kept, shotAt,\n  };\n}\n",
  "playbooks/launch-videos/kit/edit/brand.js": "// Who the video is for. Files named here live in media/brand/ (never committed).\nexport const BRAND = {\n  name: \"Acme\",\n  // The real mark (SVG or PNG), shown in the corner and on the end card. null hides it.\n  mark: \"media/brand/mark.svg\",\n  // The product's own font file; null uses the system font. Normal tracking only.\n  font: { family: \"Inter\", file: \"media/brand/Inter.woff2\" },\n  // The end card's one line, in the user's words.\n  cta: \"Try it free at acme.com\",\n  // Behind UI shots and a plain end card. Light and quiet; no gradients.\n  background: \"#f3f2ee\",\n  // Layout size: 1920×1080 for launch posts and sites, 1080×1920 for vertical. Renders scale it (0.5 to review, 2 for 4K).\n  canvas: { width: 1920, height: 1080 },\n};\n",
  "playbooks/launch-videos/kit/edit/capture.js": "// Product UI states to capture with scripts/capture.mjs (see the product-demo format for an example).\nexport const VIEWPORT = { width: 1440, height: 900 };\nexport const CAPTURES = [];\n",
  "playbooks/launch-videos/kit/edit/speech.js": "// Written by scripts/speech.mjs from word timings. Do not edit by hand.\nexport const SPEECH = [];\n",
  "playbooks/launch-videos/kit/formats/irl/edit/scenes.js": "// Glass components over the open side of a shot, timed to what is said (see the overlays step).\n// Each: shot, a (in), b (out; scenes sharing b leave together), x (from the outer edge), y (from the top margin),\n// w (width), body (markup from page/primitives.js), and optional from/to offsets, hl (selected at), update(el, t).\n// a, b and hl are on the shot's clock (seconds in the clip file); live content runs in output seconds, so wrap its\n// times in place(). Pieces of one scene stack with at least 12px between them.\nimport { place } from \"./timeline.js\";\nimport { row, pill, stat, check, toggle, flip } from \"../page/primitives.js\";\n\nexport const SCENES = [\n  { shot: \"intro\", a: 4.8, b: 8.6, x: 0, y: 0, w: 760, body: row({ title: \"Invoice #1042\", sub: \"Northwind · due Friday\", right: pill(\"$4,200\") }) },\n  { shot: \"intro\", a: 5.1, b: 8.6, x: 0, y: 176, w: 760, body: row({ title: \"Approved\", sub: \"Just now\", right: check }) },\n  { shot: \"how\", a: 5.2, b: 99, x: 0, y: 0, w: 640, body: stat(\"2 min\", \"to connect your inbox\") },\n  { shot: \"how\", a: 6.0, b: 99, x: 0, y: 330, w: 640, body: row({ title: \"Auto-file\", right: toggle }), update: flip(place(\"how\", 6.6)), still: 7.1 },\n];\n",
  "playbooks/launch-videos/kit/formats/irl/edit/timeline.js": "// The edit: filmed clips in order, headlines timed to the words, glass on the open side, and the end card.\n// Clip times are seconds in the clip file (the transcript's clock); the end card's are from its own start.\n// Clips live in media/clips/; measure their length with ffmpeg -i.\nimport { build } from \"../core/timeline.js\";\nimport { BRAND } from \"./brand.js\";\n\nexport const { WIDTH, HEIGHT, FPS, FRAMES, TOTAL, LAYOUT, SHOTS, SHOT, HEADLINES, NARRATION, MUSIC, CUTS, place, kept, shotAt } = build({\n  canvas: BRAND.canvas,\n  // Match the camera: 24000 / 1001 for 23.976 footage, 30 for 30p.\n  fps: 24000 / 1001,\n  shots: [\n    // overlays: the side with open space (the speaker stands on the other). corner: the free top corner for the mark.\n    // A launch film plays its clips whole. To start on the first word or tighten a long pause, give the clip\n    // keep: [[from, to], ...] from node scripts/pauses.mjs instead of from/to.\n    { id: \"intro\", kind: \"clip\", file: \"clip1.mov\", from: 0, to: 12, overlays: \"right\", corner: \"left\" },\n    { id: \"how\", kind: \"clip\", file: \"clip2.mov\", from: 0, to: 14, overlays: \"left\", corner: \"right\" },\n    // The end card plays over a quiet clip (its sound kept low), or over the brand background without `file`.\n    { id: \"end\", kind: \"end\", file: \"end.mov\", from: 0.5, to: 6.5 },\n  ],\n  // [shot, start, end, side, \"line one|line two\"]. Each spans a whole phrase and holds at least 2.2s.\n  headlines: [\n    [\"intro\", 0.2, 4.6, \"left\", \"Acme|Every invoice, one inbox\"],\n    [\"how\", 0.3, 4.8, \"right\", \"Ready in|two minutes\"],\n  ],\n  // Off by default. With the user's go-ahead: a licensed or generated track at media/music.wav, ducked under speech.\n  music: null,\n});\n",
  "playbooks/launch-videos/kit/formats/product-demo/edit/capture.js": "// Product UI states, captured from the real app with scripts/capture.mjs (headless Chrome, 2× pixels).\n// Use a demo account with demo data: never capture real customer data. For a signed-in app, the user signs in once\n// with `node scripts/capture.mjs --login <url>`, which saves media/auth.json; you never type their password.\n// Each capture: name, url, optional actions (click, fill, press, wait, scroll) run before the shot, and targets\n// (CSS selectors) whose boxes the camera and cursor use as \"<capture>.<target>\".\nexport const VIEWPORT = { width: 1440, height: 900 };\nexport const CAPTURES = [\n  {\n    name: \"inbox\",\n    url: \"http://localhost:3000/inbox\",\n    waitFor: \"text=Inbox\",\n    targets: { list: \"[data-testid=invoice-list]\", first: \"[data-testid=invoice-list] > :first-child\" },\n  },\n  {\n    name: \"invoice-open\",\n    url: \"http://localhost:3000/inbox\",\n    actions: [{ click: \"[data-testid=invoice-list] > :first-child\" }, { waitFor: \"text=Approve\" }],\n    targets: { total: \"[data-testid=invoice-total]\", approve: \"button:has-text('Approve')\" },\n  },\n];\n",
  "playbooks/launch-videos/kit/formats/product-demo/edit/scenes.js": "// Glass components are optional in a product demo: the product is the picture. Use them for a number or a result\n// the UI does not show (see the overlays step). Same shape as in an IRL video; set the shot's overlays side first.\nexport const SCENES = [];\n",
  "playbooks/launch-videos/kit/formats/product-demo/edit/timeline.js": "// The edit: captured UI states of the real product, a camera that glides between the parts that matter, a cursor,\n// narration timed to the words, and the end card. Times are seconds from the start of each shot.\nimport { build } from \"../core/timeline.js\";\nimport { BRAND } from \"./brand.js\";\n\nexport const { WIDTH, HEIGHT, FPS, FRAMES, TOTAL, LAYOUT, SHOTS, SHOT, HEADLINES, NARRATION, MUSIC, CUTS, place, kept, shotAt } = build({\n  canvas: BRAND.canvas,\n  fps: 30,\n  shots: [\n    {\n      id: \"inbox\", kind: \"ui\", len: 7,\n      // Which captured state is on screen (edit/capture.js names). A new state replaces the old one instantly, like the app.\n      images: [{ at: 0, capture: \"inbox\" }, { at: 3.4, capture: \"invoice-open\" }],\n      // Camera: glides to a captured target (capture.target) at a zoom; omit target for the whole screen. Zoom ≤ 1.8.\n      camera: [{ at: 0 }, { at: 1.2, target: \"inbox.list\", zoom: 1.35 }, { at: 3.6, target: \"invoice-open.total\", zoom: 1.6 }],\n      // Cursor: glides to a target, then clicks. Clicks land on the frame where the next state appears.\n      cursor: [{ at: 0.6, target: \"inbox.first\" }, { at: 3.4, click: true }],\n      overlays: null,\n    },\n    { id: \"end\", kind: \"end\", len: 5 },\n  ],\n  headlines: [\n    [\"inbox\", 0.3, 3.2, \"left\", \"Every invoice|in one inbox\"],\n    [\"inbox\", 3.6, 6.7, \"left\", \"Approve|in one click\"],\n  ],\n  // [shot, start, file]: media/narration/<file>.wav (wallet text to speech) with media/words/<file>.json.\n  narration: [\n    [\"inbox\", 0.3, \"line-1\"],\n    [\"inbox\", 3.6, \"line-2\"],\n  ],\n  music: null,\n});\n",
  "playbooks/launch-videos/kit/formats/reel/edit/scenes.js": "// Big glass cards centred in the open space above the speaker's head, one idea each, timed to the words.\n// Each: shot, a (in), b (out), y (top, in px), w (width), body, and optional update(el, t), still (when live content\n// stops) and loop. a, b and still are seconds in the clip file; live content runs in output seconds, so wrap its times\n// in place(). Rules from review:\n// - y: 412 under a two-line headline, 335 under a one-line headline. The overlap audit keeps every card 8px above the\n//   measured head line on every frame, out of the Reels top bar (200px) and the bottom 350px.\n// - A card leaves when its headline starts to leave (b = that headline's end minus about 0.9s), so the next headline\n//   never rises through it, and enters at least 0.3s after its own headline.\n// - Logos are real files in media/brand/; demo values (calendar times, mail logos) are named as demo at handover.\nimport { place } from \"./timeline.js\";\nimport { BRAND } from \"./brand.js\";\nimport { row, pill, tile, chips, reveal, capsule, widen, claim, countUp } from \"../page/primitives.js\";\n\nconst at = (t) => place(\"reel\", t);\n\nexport const SCENES = [\n  { shot: \"reel\", a: 5.4, b: 8.3, y: 412, w: 920, body: row({ lead: tile(BRAND.mark ?? \"\", 120), title: \"Meetings booked\", sub: \"Every day\", right: `<span class=\"pill count\">0</span>` }),\n    update: countUp(6, at(6.1), 1.0), still: 7.2 },\n  // The cut before \"It answers\" lands its headline at 13.69s, so this card waits until 14.05s (0.3s or more).\n  { shot: \"reel\", a: 14.05, b: 22.4, y: 412, body: chips(tile(BRAND.mark ?? \"\", 120), [\"Sent\", \"Replied\"]),\n    update: reveal([[\".k0\", at(14.4)], [\".k1\", at(15.1)]]), still: 15.7 },\n  { shot: \"reel\", a: 23.95, b: 99, y: 335, body: capsule(\"acme.com/demo\"), update: widen(at(23.95)), still: 25.75 },\n  { shot: \"reel\", a: 26.4, b: 99, y: 497, body: claim(\"Entirely free\") },\n];\n",
  "playbooks/launch-videos/kit/formats/reel/edit/timeline.js": "// A reel: one selfie clip, vertical, with a hook, headlines and big glass cards in the open space above the head,\n// light cuts, and a link call to action. Times are seconds in the clip file (the transcript's clock); a time inside a\n// removed pause lands on the cut. The clip lives in media/clips/.\nimport { build } from \"../core/timeline.js\";\n\nexport const { WIDTH, HEIGHT, FPS, FRAMES, TOTAL, LAYOUT, SHOTS, SHOT, HEADLINES, NARRATION, MUSIC, CUTS, place, kept, shotAt } = build({\n  canvas: { width: 1080, height: 1920 },\n  fps: 30,\n  layout: \"reel\",\n  shots: [\n    // Start on the first word and tighten only the big pauses: paste the keep ranges node scripts/pauses.mjs suggests,\n    // then read its \"not cut\" lines. No end card: the call to action plays over the speaker and holds to the end.\n    { id: \"reel\", kind: \"clip\", file: \"reel.mov\", keep: [[1.07, 12.7], [13.17, 28.0]] },\n  ],\n  // [shot, start, end, \"top\", \"line one|line two\", { hook, logo }]. The hook is on screen from the first frame (start\n  // it a beat before the first kept second), in the speaker's own words. The last headline holds to the end (99).\n  headlines: [\n    [\"reel\", 0.95, 4.95, \"top\", \"Founder shares|the secret to sales\", { hook: true }],\n    [\"reel\", 5.0, 9.2, \"top\", \"0 → 6 meetings|booked every day\"],\n    [\"reel\", 9.25, 13.0, \"top\", \"One free,|open-source tool\"],\n    [\"reel\", 13.05, 23.3, \"top\", \"It answers|for you\"],\n    [\"reel\", 23.3, 99, \"top\", \"Book a time\"],\n  ],\n  music: null,\n});\n",
  "playbooks/launch-videos/kit/page/end-card.js": "// End card: the mark appears in a glass circle that widens into a pill as the name slides out beside it, and a\n// glass caption with the call to action rises beneath, its words filling in one after another. It holds to the\n// last frame: no fade to black.\nimport { BRAND } from \"../edit/brand.js\";\nimport { p, outCubic, glide, ease, move } from \"../core/motion.js\";\n\nconst escape = (value) => value.replace(/[&<>]/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\" })[c]);\n\nexport function renderEnd(host, t, plain) {\n  host.replaceChildren();\n  const el = document.createElement(\"div\");\n  el.className = `end-card${plain ? \" plain\" : \"\"}`;\n  el.innerHTML = `<div class=\"end-pill\">${BRAND.mark ? `<span class=\"mk\"><img class=\"mark\" src=\"/${BRAND.mark}\" alt=\"\"></span>` : \"\"}<span class=\"word\">${escape(BRAND.name)}</span></div>\n    <div class=\"end-cta\"><span class=\"txt\">${BRAND.cta.split(\" \").map((w) => `<span>${escape(w)}</span>`).join(\" \")}</span></div>`;\n  host.appendChild(el);\n  const pill = el.querySelector(\".end-pill\"), word = el.querySelector(\".word\"), cta = el.querySelector(\".end-cta\");\n  const appear = p(t, 0.35, 0.7, outCubic), rise = p(t, 0.35, 1.2, glide), widen = BRAND.mark ? p(t, 1.05, 1.1, glide) : 1;\n  const closed = 144, open = (BRAND.mark ? 144 : 0) + word.offsetWidth + (BRAND.mark ? 0 : 54);\n  pill.style.width = `${(closed + (open - closed) * widen).toFixed(2)}px`;\n  pill.style.opacity = appear >= 0.999 ? \"\" : appear.toFixed(4);\n  pill.style.filter = appear < 0.999 ? `blur(${((1 - appear) * 12).toFixed(2)}px)` : \"\";\n  pill.style.transform = `perspective(100px) translate3d(-50%, ${((1 - rise) * 40).toFixed(3)}px, 0) scale(${(0.9 + 0.1 * rise).toFixed(5)})`;\n  word.style.opacity = BRAND.mark ? p(t, 1.35, 0.6, outCubic).toFixed(4) : \"\";\n  word.style.transform = move((1 - p(t, 1.2, 1.0, glide)) * -26, 0);\n  const c = p(t, 2.3, 1.1, glide), cf = p(t, 2.3, 0.5, outCubic);\n  cta.style.opacity = cf >= 0.999 ? \"\" : cf.toFixed(4);\n  cta.style.filter = cf < 0.999 ? `blur(${((1 - cf) * 10).toFixed(2)}px)` : \"\";\n  cta.style.transform = `perspective(100px) translate3d(-50%, ${((1 - c) * 36).toFixed(3)}px, 0)`;\n  [...el.querySelectorAll(\".end-cta .txt > span\")].forEach((span, i) => {\n    span.style.opacity = (0.35 + 0.65 * p(t, 2.7 + i * 0.08, 0.5, ease)).toFixed(4);\n  });\n}\n\n/** When the end card has fully settled (seconds from its start), for the stillness audit. */\nexport const endSettled = () => 2.7 + BRAND.cta.split(\" \").length * 0.08 + 0.6;\n",
  "playbooks/launch-videos/kit/page/frame.js": "// Draws one complete frame for any second of the timeline: the picture (footage or product UI), glass overlays,\n// the corner mark, the end card and headlines. The footage is drawn inside the page so glass can blur real pixels.\n// Scripts call window.renderFrame(t), then window.settle(), then wait two animation frames before capturing.\nimport { BRAND } from \"../edit/brand.js\";\nimport { SHOTS, FPS, WIDTH, HEIGHT, LAYOUT, shotAt } from \"../edit/timeline.js\";\nimport { renderHeadlines } from \"./headlines.js\";\nimport { renderOverlays, MARGIN } from \"./overlays.js\";\nimport { renderUi } from \"./ui-shot.js\";\nimport { renderEnd } from \"./end-card.js\";\n\nconst $ = (id) => document.getElementById(id);\nconst layers = { base: $(\"base\"), footage: $(\"footage\"), ui: $(\"ui\"), overlays: $(\"overlays\"), stage: $(\"stage\"), cursor: $(\"cursor\"), heads: $(\"heads\") };\nwindow.layers = layers;\nObject.assign(document.body.style, { width: `${WIDTH}px`, height: `${HEIGHT}px`, background: BRAND.background });\ndocument.body.classList.add(`layout-${LAYOUT}`);\ndocument.documentElement.style.setProperty(\"--font\", BRAND.font ? `\"${BRAND.font.family}\"` : \"system-ui\");\nif (BRAND.font?.file) document.fonts.add(await new FontFace(BRAND.font.family, `url(/${BRAND.font.file})`).load());\nconst manifest = SHOTS.some((shot) => shot.kind === \"ui\") ? await (await fetch(\"/output/ui/manifest.json\")).json() : null;\n// ?scale=0.5|1|2 picks the footage frames prepared at that scale.\nconst FOOTAGE = `/output/footage/${new URLSearchParams(location.search).get(\"scale\") ?? \"1\"}`;\nconst corner = document.createElement(\"div\");\ncorner.className = \"corner-mark\";\nif (BRAND.mark) corner.innerHTML = `<img class=\"mark\" src=\"/${BRAND.mark}\" alt=\"\">`;\ndocument.body.appendChild(corner);\nlet footageSrc = \"\";\n\nconst hasFootage = (shot) => shot.kind === \"clip\" || (shot.kind === \"end\" && Boolean(shot.file));\n\nwindow.renderFrame = async (t) => {\n  const shot = shotAt(t), local = t - shot.at;\n  const src = hasFootage(shot)\n    ? `${FOOTAGE}/${shot.id}/f${String(Math.min(Math.round(shot.len * FPS) - 1, Math.max(0, Math.round(local * FPS)))).padStart(6, \"0\")}.jpg`\n    : \"\";\n  if (src !== footageSrc) {\n    footageSrc = src;\n    layers.footage.style.visibility = src ? \"visible\" : \"hidden\";\n    if (src) { layers.footage.src = src; await layers.footage.decode().catch(() => {}); }\n  }\n  document.body.classList.toggle(\"on-ui\", shot.kind === \"ui\");\n  if (shot.kind === \"ui\") await renderUi(layers.ui, layers.cursor, manifest, shot, local, WIDTH, HEIGHT);\n  else { layers.ui.replaceChildren(); layers.cursor.replaceChildren(); }\n  renderOverlays(layers.overlays, shot, t, WIDTH);\n  if (shot.kind === \"end\") renderEnd(layers.stage, local, !hasFootage(shot));\n  else layers.stage.replaceChildren();\n  renderHeadlines(layers.heads, t);\n  // The mark stays still and whole in the free top corner, and moves only on a cut.\n  // Reels carry no corner mark: the mark appears in the call-to-action capsule instead.\n  const side = shot.kind !== \"end\" && LAYOUT !== \"reel\" && BRAND.mark ? shot.corner : null;\n  corner.style.display = side ? \"block\" : \"none\";\n  corner.style.left = side === \"left\" ? `${MARGIN}px` : \"auto\";\n  corner.style.right = side === \"right\" ? `${MARGIN}px` : \"auto\";\n};\n\n// Resolves once fonts and every image have decoded, so no frame catches a half-loaded image.\nwindow.settle = async () => {\n  await document.fonts.ready;\n  await Promise.all([...document.images].map((img) => (img.complete ? img.decode().catch(() => {}) : new Promise((r) => { img.onload = img.onerror = r; }))));\n};\n",
  "playbooks/launch-videos/kit/page/headlines.js": "// Headlines with a measured \"Vertical Slide\": each line rises about 145px on a strong ease-out, reaches full\n// brightness within a few frames (the second line 0.1s behind), holds perfectly still, then lifts about 70px\n// over up to 0.9s and fades through the second half of that. Rebuilt from scratch on every frame. They sit low on\n// the open side (left, right, center), or centred at the top of a reel (top).\nimport { HEADLINES } from \"../edit/timeline.js\";\nimport { p, outCubic, expoOut, ease, move } from \"../core/motion.js\";\n\nconst escape = (value) => value.replace(/[&<>]/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\" })[c]);\n\nexport function renderHeadlines(host, t) {\n  host.replaceChildren();\n  for (const hl of HEADLINES) {\n    if (t < hl.at || t >= hl.end) continue;\n    const el = document.createElement(\"div\");\n    el.className = `headline ${hl.side}${hl.hook ? \" hook\" : \"\"}`;\n    // A real credibility mark (a file in media/) can sit before the first line, sized to the cap height.\n    const mark = hl.logo ? `<img class=\"inline-mark\" src=\"/${hl.logo}\" alt=\"\">` : \"\";\n    el.innerHTML = hl.lines.map((line, i) => `<div class=\"line\">${i === 0 ? mark : \"\"}${escape(line)}</div>`).join(\"\");\n    host.appendChild(el);\n    // Short headlines compress the exit so it never collides with the entrance.\n    const exitDur = Math.min(0.9, Math.max(0.55, hl.end - hl.at - 1.4));\n    [...el.children].forEach((line, i) => {\n      const a = hl.at + i * 0.1;\n      const rise = p(t, a, 1.1, expoOut), appear = p(t, a, 0.18, outCubic);\n      const exitAt = hl.end - exitDur - 0.05 + i * 0.05;\n      const lift = p(t, exitAt, exitDur, ease), vanish = p(t, exitAt + exitDur * 0.35, exitDur * 0.65, ease);\n      const opacity = appear * (1 - vanish);\n      line.style.opacity = opacity >= 0.9999 ? \"\" : opacity.toFixed(4);\n      line.style.transform = move(0, (1 - rise) * 145 - lift * 70);\n    });\n  }\n}\n",
  "playbooks/launch-videos/kit/page/index.html": "<!doctype html>\n<html><head><meta charset=\"utf-8\"><link rel=\"stylesheet\" href=\"/page/styles.css\"></head>\n<body><div id=\"base\"><img id=\"footage\" alt=\"\"><div id=\"ui\"></div></div><div id=\"overlays\"></div><div id=\"stage\"></div><div id=\"cursor\"></div><div id=\"heads\"></div>\n<script type=\"module\" src=\"/page/frame.js\"></script></body></html>\n",
  "playbooks/launch-videos/kit/page/overlays.js": "// Glass components with one motion system: a long overshoot-free glide in, the whole scene settling together like a\n// camera easing back, stillness while it holds, and a smooth lift out while the next scene rises in. Every piece is\n// rebuilt on every frame, so its pixels depend only on the time, never on which renderer page drew it before.\n// Side layout: pieces stack on the shot's open side. Reel layout: pieces are centred at their `y`, above the head.\nimport { SCENES } from \"../edit/scenes.js\";\nimport { LAYOUT, place } from \"../edit/timeline.js\";\nimport { p, outCubic, glide, ease, move } from \"../core/motion.js\";\n\nexport const MARGIN = 56;\n// Scene times are on the shot's clock (source seconds for a clip); everything here runs in output seconds.\nconst timed = SCENES.map((e) => ({ ...e, at: place(e.shot, e.a), out: place(e.shot, e.b) }));\n// A scene is the pieces of one shot that leave together (same b).\nconst sceneStart = (e) => Math.min(...timed.filter((o) => o.shot === e.shot && o.b === e.b).map((o) => o.at));\n\nexport function renderOverlays(host, shot, t, width) {\n  host.replaceChildren();\n  const side = shot.overlays;\n  const reel = LAYOUT === \"reel\";\n  if (!reel && side !== \"left\" && side !== \"right\") return;\n  for (const e of timed) {\n    if (e.shot !== shot.id || t < e.at || t >= e.out + 0.75) continue;\n    const el = document.createElement(\"div\");\n    el.className = \"piece\";\n    el.innerHTML = e.body;\n    if (e.w) el.style.width = `${e.w}px`;\n    host.appendChild(el);\n    // Live content first: a capsule that widens changes the width the piece is centred by.\n    e.update?.(el, t);\n    const k = p(t, e.at, 1.05, glide);\n    const fade = p(t, e.at, 0.45, outCubic);\n    const g = p(t, sceneStart(e), 1.3, glide);\n    const out = e.out > shot.end ? 0 : p(t, e.out, 0.7, ease);\n    const [fx, fy] = e.from ?? [0, reel ? 26 : 40];\n    const [tx, ty] = e.to ?? [0, -46];\n    const w = e.w ?? el.offsetWidth;\n    if (reel) {\n      el.style.left = `${((width - w) / 2).toFixed(2)}px`;\n      el.style.top = `${e.y}px`;\n      el.style.transformOrigin = `${w / 2}px 0px`;\n    } else {\n      el.style.left = `${side === \"right\" ? width - MARGIN - e.x - w : MARGIN + e.x}px`;\n      el.style.top = `${MARGIN + e.y}px`;\n      // The scene scales about its outer top corner.\n      el.style.transformOrigin = `${side === \"right\" ? w + e.x : -e.x}px ${-e.y}px`;\n    }\n    const settled = out === 0 && k > 0.9995 && g > 0.9995;\n    el.style.transform = settled ? move() : move((1 - k) * fx + out * tx, (1 - k) * fy + (1 - g) * (reel ? 16 : 28) + out * ty,\n      (0.965 + 0.035 * k) * (1.05 - 0.05 * g) * (1 - 0.03 * out));\n    const surface = el.firstElementChild;\n    if (!surface) continue;\n    const opacity = fade * (1 - out);\n    surface.style.opacity = opacity >= 0.999 ? \"\" : opacity.toFixed(4);\n    const blur = (1 - fade) * 14 + out * 10;\n    surface.style.filter = blur > 0.01 ? `blur(${blur.toFixed(2)}px)` : \"\";\n    if (e.hl != null) surface.classList.toggle(\"selected\", t >= place(e.shot, e.hl));\n  }\n}\n\n/** When each scene enters, has fully landed and starts to leave, in output seconds, for the audits and sound effects. */\nexport function sceneWindows() {\n  const scenes = new Map();\n  for (const e of timed) {\n    const key = `${e.shot}:${e.b}`;\n    const s = scenes.get(key) ?? { shot: e.shot, enter: Infinity, last: 0, leave: e.out, still: 0, loop: false };\n    s.enter = Math.min(s.enter, e.at);\n    s.last = Math.max(s.last, e.at);\n    // Live content (a counter, a switch) says when it stops, on the shot's clock; a loop never holds still.\n    if (e.still != null) s.still = Math.max(s.still, place(e.shot, e.still));\n    s.loop ||= Boolean(e.loop);\n    scenes.set(key, s);\n  }\n  return [...scenes.entries()].map(([key, s]) => ({\n    key, shot: s.shot, enter: s.enter, loop: s.loop, leave: s.leave, settled: Math.max(s.last + 1.15, s.enter + 1.4, s.still),\n  }));\n}\n",
  "playbooks/launch-videos/kit/page/primitives.js": "// Building blocks for glass components. Each returns markup; page/overlays.js applies the motion.\n// Logos and images are real files under media/ (the product's own, or the brands it works with). Never draw mock\n// windows, title bars or invented UI.\nimport { BRAND } from \"../edit/brand.js\";\nimport { p, glide, outCubic, move } from \"../core/motion.js\";\n\nconst src = (path) => (path.startsWith(\"/\") || path.startsWith(\"http\") ? path : `/${path}`);\nconst text = (value) => String(value).replace(/[&<>\"]/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\" })[c]);\n\n// A real logo on a glass tile.\nexport const tile = (path, size = 96) =>\n  `<span class=\"tile\" style=\"width:${size}px;height:${size}px;border-radius:${size * 0.24}px\"><img src=\"${src(path)}\" alt=\"\"></span>`;\n// Logo (optional) + title + secondary line + something on the right (a pill, a check, a switch).\nexport const row = ({ lead = \"\", title, sub = \"\", right = \"\" }) =>\n  `<div class=\"glass row\">${lead}<span class=\"txt\"><b>${text(title)}</b>${sub ? `<em>${text(sub)}</em>` : \"\"}</span>${right}</div>`;\n// A price, count or state in a near-white pill. Use real numbers that add up across the video.\nexport const pill = (value) => `<span class=\"pill\">${text(value)}</span>`;\nexport const bigPill = (value) => `<div class=\"glass big-pill\"><span class=\"count\">${text(value)}</span></div>`;\n// One big number and what it means.\nexport const stat = (big, caption) => `<div class=\"glass stat\"><span class=\"big\">${text(big)}</span><span class=\"cap\">${text(caption)}</span></div>`;\n// A cropped real screenshot or product image on glass (from output/ui/ or media/).\nexport const image = (path) => `<div class=\"glass\" style=\"padding:14px\"><img class=\"shot-img\" src=\"${src(path)}\" alt=\"\"></div>`;\nexport const check = `<svg viewBox=\"0 0 20 20\" class=\"ck\"><circle cx=\"10\" cy=\"10\" r=\"10\" fill=\"#34C759\"/><path d=\"M5.6 10.4l2.9 2.8 6-6.1\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>`;\nexport const toggle = `<span class=\"switch\"><i></i></span>`;\n// update() for a piece holding a switch: it flips on at `at` (seconds from the shot start).\nexport const flip = (at) => (el, t) => {\n  const k = p(t, at, 0.45, glide), sw = el.querySelector(\".switch\");\n  if (!sw) return;\n  sw.style.background = `rgba(${Math.round(255 - 203 * k)}, ${Math.round(255 - 56 * k)}, ${Math.round(255 - 166 * k)}, ${(0.28 + 0.62 * k).toFixed(3)})`;\n  sw.firstElementChild.style.transform = `translate3d(${(k * 40).toFixed(2)}px, 0, 0)`;\n};\n// update() for a piece holding .count: counts up to `to` from `at` over `d` seconds, then holds still.\nexport const countUp = (to, at, d = 0.9, format = (n) => n.toLocaleString(\"en-US\")) => (el, t) => {\n  const node = el.querySelector(\".count\");\n  if (node) node.textContent = format(Math.round(to * p(t, at, d)));\n};\n\n// Checked chips that land one by one on their words (Sent, Replied). Pair with reveal(\".k0\", at) and friends.\nexport const chips = (lead, labels) =>\n  `<div class=\"glass row chips\">${lead}${labels.map((label, i) => `<span class=\"pill k${i}\">${check}${text(label)}</span>`).join(\"\")}</div>`;\n// update() that fades and lifts children into a held card, each at its own output time: reveal([[\".k0\", at0], [\".k1\", at1]]).\nexport const reveal = (items) => (el, t) => {\n  for (const [selector, at] of items) {\n    const node = el.querySelector(selector);\n    if (!node) continue;\n    node.style.opacity = p(t, at, 0.3, outCubic).toFixed(4);\n    node.style.transform = move(0, (1 - p(t, at, 0.5, glide)) * 18);\n  }\n};\n// The reel's call to action: a glass capsule that widens from the mark into a link. Pair with widen(at).\nexport const capsule = (link) =>\n  `<div class=\"glass capsule\">${BRAND.mark ? `<img class=\"cm\" src=\"${src(BRAND.mark)}\" alt=\"\">` : \"\"}<span class=\"cw\">${text(link)}</span></div>`;\nexport const widen = (at) => (el, t) => {\n  const cap = el.querySelector(\".capsule\"), word = cap?.querySelector(\".cw\");\n  if (!cap || !word) return;\n  const closed = 136, open = 22 + (BRAND.mark ? 92 + 24 : 0) + word.offsetWidth + 22;\n  cap.style.width = `${(closed + (open - closed) * p(t, at + 0.55, 1.1, glide)).toFixed(2)}px`;\n  word.style.opacity = p(t, at + 0.75, 0.5, outCubic).toFixed(4);\n  word.style.transform = move((1 - p(t, at + 0.7, 1.0, glide)) * -26, 0);\n};\n// A checked closing claim (Entirely free), usually under the capsule.\nexport const claim = (value) => `<div class=\"glass claim\">${check}${text(value)}</div>`;\n",
  "playbooks/launch-videos/kit/page/styles.css": "/* Layout is in design pixels (edit/brand.js canvas); renders scale it. Light, clear glass over the real picture:\n   no dark panels, no rainbow gradients, no drop shadows, normal tracking. */\n* { box-sizing: border-box; margin: 0; padding: 0; letter-spacing: 0; }\nhtml, body { overflow: hidden; background: #000; }\nbody { font-family: var(--font), system-ui, -apple-system, \"Segoe UI\", sans-serif; -webkit-font-smoothing: antialiased; color: #fff; }\n#base, #overlays, #stage, #heads { position: absolute; inset: 0; }\n#footage { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; display: block; }\n.mark { width: 100%; height: 100%; object-fit: contain; display: block; }\n.corner-mark { position: absolute; top: 56px; width: 60px; height: 60px; }\n\n/* Glass. Only transform may sit on a wrapper (.piece): opacity, filter or will-change there would make it a\n   backdrop root, and the glass would blur nothing. Opacity and blur go on the glass surface itself. */\n.piece { position: absolute; }\n.glass, .tile, .switch, .end-pill, .end-cta {\n  -webkit-backdrop-filter: blur(4px) saturate(180%) brightness(1.06); backdrop-filter: blur(4px) saturate(180%) brightness(1.06);\n}\n.glass {\n  position: relative; display: flex; align-items: center; gap: 24px; color: #fff;\n  background: linear-gradient(150deg, rgba(255, 255, 255, .26) 0%, rgba(255, 255, 255, .10) 45%, rgba(255, 255, 255, .16) 100%);\n  border: 1px solid rgba(255, 255, 255, .55);\n  box-shadow: inset 0 1.5px 0 rgba(255, 255, 255, .75), inset 0 -1px 0 rgba(255, 255, 255, .18), inset 0 0 32px rgba(255, 255, 255, .10);\n  border-radius: 36px; text-shadow: 0 1px 2px rgba(0, 0, 0, .18), 0 1px 14px rgba(0, 0, 0, .3);\n}\n.glass::before { content: \"\"; position: absolute; inset: 0; border-radius: inherit; pointer-events: none;\n  background: linear-gradient(180deg, rgba(255, 255, 255, .26) 0%, rgba(255, 255, 255, 0) 42%); }\n.glass.selected { border-color: rgba(255, 255, 255, .9); background: linear-gradient(150deg, rgba(255, 255, 255, .36), rgba(255, 255, 255, .16)); }\n.row { padding: 24px 34px 24px 24px; min-height: 146px; }\n.row .txt { display: flex; flex-direction: column; gap: 6px; flex: 1; min-width: 0; }\n.row .txt b { font-size: 42px; font-weight: 500; line-height: 1.12; white-space: nowrap; }\n.row .txt em { font-style: normal; font-size: 30px; font-weight: 450; color: rgba(255, 255, 255, .84); }\n.row .txt:first-child { padding-left: 10px; }\n.pill { display: inline-flex; align-items: center; height: 60px; padding: 0 26px; border-radius: 30px; font-size: 34px; font-weight: 500;\n  font-variant-numeric: tabular-nums; background: rgba(255, 255, 255, .92); color: #1d1c1a; text-shadow: none; flex: none; }\n.big-pill { display: inline-flex; gap: 16px; padding: 24px 40px; font-size: 48px; font-weight: 500; font-variant-numeric: tabular-nums; }\n.stat { flex-direction: column; align-items: flex-start; gap: 8px; padding: 40px 48px; }\n.stat .big { font-size: 150px; font-weight: 500; line-height: 1; font-variant-numeric: tabular-nums; }\n.stat .cap { font-size: 36px; font-weight: 450; color: rgba(255, 255, 255, .86); }\n.ck { width: 54px; height: 54px; flex: none; }\n.tile { display: inline-grid; place-items: center; flex: none; overflow: hidden;\n  background: linear-gradient(150deg, rgba(255, 255, 255, .5), rgba(255, 255, 255, .26)); border: 1px solid rgba(255, 255, 255, .6);\n  box-shadow: inset 0 1.5px 0 rgba(255, 255, 255, .75), inset 0 0 20px rgba(255, 255, 255, .12); }\n.tile img { width: 62%; height: 62%; object-fit: contain; }\n.shot-img { display: block; width: 100%; border-radius: 24px; }\n.switch { position: relative; width: 104px; height: 64px; border-radius: 32px; flex: none; background: rgba(255, 255, 255, .28); border: 1px solid rgba(255, 255, 255, .5); }\n.switch i { position: absolute; left: 6px; top: 5px; width: 52px; height: 52px; border-radius: 50%; background: #fff; display: block; }\n\n/* Headlines: medium weight, normal tracking, low on the open side. */\n.headline { position: absolute; bottom: 72px; color: #fff; font-size: 66px; line-height: 1.16; font-weight: 500; text-shadow: 0 1px 16px rgba(0, 0, 0, .16); }\n.headline .line { white-space: nowrap; }\n.headline.left { left: 72px; }\n.headline.right { right: 72px; text-align: right; }\n.headline.center { left: 0; right: 0; text-align: center; }\n.on-ui .headline { color: #1d1c1a; text-shadow: none; }\n.headline .line:has(.inline-mark) { display: flex; align-items: center; }\n.headline.center .line:has(.inline-mark), .headline.top .line:has(.inline-mark) { justify-content: center; }\n.headline .inline-mark { width: .8em; height: .8em; margin-right: .22em; flex: none; object-fit: contain; }\n\n/* Reels (1080×1920): the speaker is centred, so headlines and glass live in the open space above the head, below the\n   Reels top bar (~200px). Nothing rests in the bottom ~350px (caption and buttons) or on the right rail. Visuals are\n   larger, because viewers watch on phones. */\n.layout-reel .headline.top { top: 214px; bottom: auto; left: 72px; right: 72px; text-align: center; font-size: 76px; line-height: 1.12;\n  text-shadow: 0 1px 16px rgba(0, 0, 0, .16), 0 1px 3px rgba(0, 0, 0, .12); }\n.layout-reel .headline.hook { font-size: 96px; line-height: 1.08; }\n.layout-reel .row { min-height: 180px; padding: 28px 40px 28px 28px; gap: 28px; border-radius: 44px; }\n.layout-reel .row .txt b { font-size: 52px; }\n.layout-reel .row .txt em { font-size: 36px; }\n.layout-reel .pill { height: 76px; padding: 0 32px; border-radius: 38px; font-size: 42px; }\n.layout-reel .stat .big { font-size: 170px; }\n.layout-reel .stat .cap { font-size: 44px; }\n.chips { padding: 30px 28px; gap: 14px; }\n.chips .pill { gap: 12px; padding: 0 30px 0 16px; }\n.chips .pill .ck { width: 46px; height: 46px; }\n/* Call to action: a glass capsule that widens from the mark into a link, and a checked claim under it. */\n.capsule { height: 136px; padding: 0 22px; gap: 24px; border-radius: 68px; overflow: hidden; justify-content: flex-start; }\n.capsule .cm { width: 92px; height: 92px; flex: none; display: block; }\n.capsule .cw { font-size: 64px; font-weight: 500; white-space: nowrap; flex: none; padding-right: 18px; }\n.claim { height: 92px; border-radius: 46px; padding: 0 36px 0 22px; gap: 16px; font-size: 44px; font-weight: 500; }\n.claim .ck { width: 52px; height: 52px; }\n\n/* Product UI: the real screen in a frameless rounded card on the brand background. */\n.ui-frame { position: absolute; overflow: hidden; border-radius: 28px; background: #fff; box-shadow: 0 0 0 1px rgba(0, 0, 0, .06); }\n.cursor { position: absolute; left: 0; top: 0; width: 34px; height: 46px; }\n.ripple { position: absolute; width: 64px; height: 64px; margin: -32px 0 0 -32px; border-radius: 50%; border: 3px solid rgba(29, 28, 26, .55); }\n\n/* End card: a glass pill holding the mark and name, and a glass caption beneath. Clearer than other glass. */\n.end-card { position: absolute; inset: 0; }\n.end-pill, .end-cta {\n  position: absolute; left: 50%; display: flex; align-items: center; overflow: hidden; white-space: nowrap; color: #fff;\n  background: linear-gradient(150deg, rgba(255, 255, 255, .14) 0%, rgba(255, 255, 255, .04) 50%, rgba(255, 255, 255, .08) 100%);\n  border: 1px solid rgba(255, 255, 255, .5); box-shadow: inset 0 1.5px 0 rgba(255, 255, 255, .7), inset 0 0 28px rgba(255, 255, 255, .08);\n  text-shadow: 0 1px 2px rgba(0, 0, 0, .18), 0 1px 14px rgba(0, 0, 0, .3);\n}\n.end-pill { top: calc(50% - 156px); height: 144px; border-radius: 72px; padding-left: 27px; }\n.end-pill .mk { width: 90px; height: 90px; flex: none; }\n.end-pill .word { padding-left: 20px; padding-right: 36px; font-size: 76px; font-weight: 500; line-height: 1; }\n.end-cta { top: calc(50% + 32px); height: 94px; border-radius: 47px; padding: 0 44px; font-size: 39px; font-weight: 450; }\n.plain .end-pill, .plain .end-cta { color: #1d1c1a; text-shadow: none; background: rgba(255, 255, 255, .7); border-color: rgba(0, 0, 0, .06); }\n",
  "playbooks/launch-videos/kit/page/ui-shot.js": "// A product UI shot: the real captured screen in a frameless card, a camera that glides between the parts that\n// matter, and a cursor that glides and clicks. Every position is a pure function of time; nothing drifts while it\n// holds. Targets (\"capture.target\") are the boxes scripts/capture.mjs measured in the real app.\nimport { p, glide, ease, clamp, lerp, move } from \"../core/motion.js\";\n\nconst POINTER = `<svg class=\"cursor\" viewBox=\"0 0 34 46\"><path d=\"M2 2v36l9.5-9 6.5 15 6-2.6-6.4-14.6H31z\" fill=\"#1d1c1a\" stroke=\"#fff\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/></svg>`;\n\nexport function uiGeometry(manifest, width, height) {\n  const { width: vw, height: vh } = manifest.viewport;\n  // Leave the bottom band for headlines and equal margins elsewhere.\n  const fit = Math.min((width - 2 * 56) / vw, (height - 2 * 56 - 200) / vh);\n  // Whole pixels, so the card is never resampled on its way to the screen.\n  const w = Math.round(vw * fit), h = Math.round(vh * fit);\n  return { vw, vh, fit: w / vw, w, h, left: Math.round((width - w) / 2), top: 56 };\n}\n\nfunction rect(manifest, ref) {\n  const [capture, target] = ref.split(\".\");\n  const box = manifest.captures[capture]?.targets?.[target];\n  if (!box) throw new Error(`No captured target \"${ref}\". Add it to edit/capture.js and run the capture again.`);\n  return box;\n}\n\n// Camera state: zoom and the image point at the centre of the card.\nfunction cameraState(manifest, g, key) {\n  if (!key.target) return { z: 1, cx: g.vw / 2, cy: g.vh / 2 };\n  const box = rect(manifest, key.target);\n  const z = clamp(key.zoom ?? Math.min(0.7 * g.vw / box.width, 0.7 * g.vh / box.height), 1, 1.8);\n  const half = [g.vw / (2 * z), g.vh / (2 * z)];\n  return { z, cx: clamp(box.x + box.width / 2, half[0], g.vw - half[0]), cy: clamp(box.y + box.height / 2, half[1], g.vh - half[1]) };\n}\nconst mix = (a, b, k) => ({ z: Math.exp(lerp(Math.log(a.z), Math.log(b.z), k)), cx: lerp(a.cx, b.cx, k), cy: lerp(a.cy, b.cy, k) });\n\n/** Where the camera is at `t`. A move that starts before the previous one finished starts from where it got to. */\nexport function cameraAt(manifest, g, keys, t) {\n  let from = { z: 1, cx: g.vw / 2, cy: g.vh / 2 }, seg = null;\n  for (const key of keys ?? []) {\n    if (key.at > t) break;\n    if (seg) from = mix(seg.from, seg.to, p(key.at, seg.key.at, seg.key.dur ?? 1.3, ease));\n    seg = { from, to: cameraState(manifest, g, key), key };\n  }\n  return seg ? mix(seg.from, seg.to, p(t, seg.key.at, seg.key.dur ?? 1.3, ease)) : from;\n}\n\n/** Where the pointer is (image coordinates), and how far into a click it is. */\nexport function cursorAt(manifest, g, keys, t) {\n  const moves = (keys ?? []).filter((key) => key.target);\n  if (!moves.length || t < moves[0].at) return null;\n  const point = (key) => { const box = rect(manifest, key.target); return [box.x + box.width / 2, box.y + box.height / 2]; };\n  const first = point(moves[0]);\n  let at = [first[0] + 140, first[1] + 160];\n  for (const key of moves) {\n    if (key.at > t) break;\n    const to = point(key), k = p(t, key.at, key.dur ?? 0.9, glide);\n    at = [lerp(at[0], to[0], k), lerp(at[1], to[1], k)];\n  }\n  const click = (keys ?? []).filter((key) => key.click && key.at <= t).at(-1);\n  return { x: at[0], y: at[1], appear: p(t, moves[0].at, 0.3), click: click ? t - click.at : null };\n}\n\n// Decoded screenshots, kept per page. The pixels drawn depend only on the image and the camera, never on history.\nconst images = new Map();\nasync function load(src) {\n  let img = images.get(src);\n  if (!img) { img = new Image(); img.src = src; images.set(src, img); }\n  await img.decode();\n  return img;\n}\n\nexport async function renderUi(host, cursorHost, manifest, shot, t, width, height) {\n  host.replaceChildren();\n  cursorHost.replaceChildren();\n  const g = uiGeometry(manifest, width, height);\n  const state = (shot.images ?? []).filter((item) => item.at <= t).at(-1) ?? shot.images?.[0];\n  if (!state) throw new Error(`UI shot \"${shot.id}\" has no images`);\n  const capture = manifest.captures[state.capture];\n  if (!capture) throw new Error(`No capture named \"${state.capture}\". Run node scripts/capture.mjs.`);\n  const cam = cameraAt(manifest, g, shot.camera, t);\n  const img = await load(`/output/ui/${capture.image}`);\n  // The camera crops the screenshot and draws it at exact device pixels on a canvas. A CSS scale transform (or a\n  // resized <img>) let Chrome resample it slightly differently depending on the page's history, so a held zoom was\n  // not pixel-identical across renderer pages.\n  const frame = document.createElement(\"div\");\n  frame.className = \"ui-frame\";\n  Object.assign(frame.style, { left: `${g.left}px`, top: `${g.top}px`, width: `${g.w}px`, height: `${g.h}px` });\n  const canvas = document.createElement(\"canvas\"), dpr = window.devicePixelRatio;\n  canvas.width = Math.round(g.w * dpr);\n  canvas.height = Math.round(g.h * dpr);\n  Object.assign(canvas.style, { width: `${g.w}px`, height: `${g.h}px`, display: \"block\" });\n  const k = img.naturalWidth / g.vw, sw = g.vw / cam.z, sh = g.vh / cam.z;\n  const ctx = canvas.getContext(\"2d\");\n  ctx.imageSmoothingEnabled = true;\n  ctx.imageSmoothingQuality = \"high\";\n  ctx.drawImage(img, (cam.cx - sw / 2) * k, (cam.cy - sh / 2) * k, sw * k, sh * k, 0, 0, canvas.width, canvas.height);\n  frame.appendChild(canvas);\n  host.appendChild(frame);\n  const pointer = cursorAt(manifest, g, shot.cursor, t);\n  if (!pointer) return;\n  const x = g.left + g.w / 2 + (pointer.x - cam.cx) * g.fit * cam.z, y = g.top + g.h / 2 + (pointer.y - cam.cy) * g.fit * cam.z;\n  if (pointer.click !== null && pointer.click < 0.5) {\n    const ripple = document.createElement(\"div\"), k = p(pointer.click, 0, 0.5, ease);\n    ripple.className = \"ripple\";\n    ripple.style.left = `${x}px`;\n    ripple.style.top = `${y}px`;\n    ripple.style.transform = `perspective(100px) translate3d(0, 0, 0) scale(${(0.4 + 0.8 * k).toFixed(4)})`;\n    ripple.style.opacity = (1 - k).toFixed(4);\n    cursorHost.appendChild(ripple);\n  }\n  cursorHost.insertAdjacentHTML(\"beforeend\", POINTER);\n  const el = cursorHost.lastElementChild;\n  const press = pointer.click !== null && pointer.click < 0.3 ? 1 - 0.12 * Math.sin(Math.PI * pointer.click / 0.3) : 1;\n  el.style.transformOrigin = \"2px 2px\";\n  el.style.transform = move(x - 2, y - 2, press);\n  el.style.opacity = pointer.appear >= 0.999 ? \"\" : pointer.appear.toFixed(4);\n}\n",
  "playbooks/launch-videos/kit/scripts/audit/overlap.mjs": "// The layout check. Side layout: at the moment each glass scene has landed, every piece sits inside the 56px margin,\n// at least 12px from every other piece, and clear of the headline on screen. Reel layout: on every frame, headlines\n// and glass stay inside the side margins and below the Reels top bar, glass stays above the bottom 350px (caption and\n// buttons) and at least 8px above the speaker's head line, and no headline crosses glass.\n// Usage: node scripts/audit/overlap.mjs\nimport { chromium } from \"playwright-core\";\nimport { existsSync, readFileSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { FPS, FRAMES, HEIGHT, LAYOUT, SHOTS, WIDTH, shotAt } from \"../../edit/timeline.js\";\nimport { sceneWindows, MARGIN } from \"../../page/overlays.js\";\nimport { launchOptions, OUT } from \"../lib/config.mjs\";\nimport { openFramePage } from \"../lib/browser.mjs\";\nimport { startServer } from \"../lib/server.mjs\";\n\nconst server = await startServer();\nconst browser = await chromium.launch(launchOptions());\nconst frame = await openFramePage(browser, server, 1);\nconst boxes = () => frame.page.evaluate(() => {\n  const visible = (el) => Number(getComputedStyle(el).opacity) > 0.05;\n  const box = (kind, el) => { const r = el.getBoundingClientRect(); return { kind, name: (el.textContent ?? \"\").trim().slice(0, 30), l: r.left, t: r.top, r: r.right, b: r.bottom, rest: el.offsetTop }; };\n  // Headlines are measured line by line, as drawn (a line lifting out has left its resting box); `rest` is where its\n  // headline sits when still, for the top bar check. Glass is measured by its visible surface.\n  return [\n    ...[...document.querySelectorAll(\"#overlays .piece\")].filter((el) => !el.firstElementChild || visible(el.firstElementChild))\n      .map((el) => box(\"piece\", el.firstElementChild ?? el)).map((b, i) => ({ ...b, rest: document.querySelectorAll(\"#overlays .piece\")[i]?.offsetTop ?? b.rest })),\n    ...[...document.querySelectorAll(\"#heads .headline .line\")].filter(visible).map((el) => ({ ...box(\"headline\", el), rest: el.parentElement.offsetTop })),\n  ];\n});\nconst gap = (a, b) => Math.max(b.l - a.r, a.l - b.r, b.t - a.b, a.t - b.b);\nconst problems = [];\n\nif (LAYOUT === \"reel\") {\n  const heads = Object.fromEntries(SHOTS.filter((s) => s.kind === \"clip\").map((s) => {\n    const file = join(OUT, \"head\", `${s.id}.json`);\n    return [s.id, existsSync(file) ? JSON.parse(readFileSync(file, \"utf8\")) : null];\n  }));\n  for (const [id, line] of Object.entries(heads)) if (!line) problems.push(`${id}: no head line measured. Run node scripts/prepare.mjs first.`);\n  for (let f = 0; f < FRAMES; f++) {\n    const t = f / FPS, shot = shotAt(t);\n    await frame.draw(t);\n    const all = await boxes(), pieces = all.filter((b) => b.kind === \"piece\"), lines = all.filter((b) => b.kind === \"headline\");\n    const head = heads[shot.id]?.[Math.min(heads[shot.id].length - 1, Math.round((t - shot.at) * FPS))];\n    for (const h of lines) if (h.rest < 200) problems.push(`${f}: headline \"${h.name}\" rests under the Reels top bar`);\n    for (const p of pieces) {\n      if (p.l < MARGIN - 1 || p.r > WIDTH - MARGIN + 1) problems.push(`${f}: \"${p.name}\" leaves the side margins`);\n      if (p.rest < 200 || p.b > HEIGHT - 350) problems.push(`${f}: \"${p.name}\" is under the Reels top bar or buttons`);\n      if (head != null && p.b > head - 8) problems.push(`${f}: \"${p.name}\" ends at ${Math.round(p.b)}px, over the head at ${head}px`);\n      for (const h of lines) if (gap(h, p) < 0) problems.push(`${f}: headline \"${h.name}\" crosses \"${p.name}\"`);\n    }\n  }\n  console.log(`${FRAMES} frames checked, ${problems.length} layout problems`);\n} else {\n  const scenes = sceneWindows();\n  for (const scene of scenes) {\n    await frame.draw(Math.min(scene.settled, scene.leave - 0.05));\n    const all = await boxes();\n    for (let i = 0; i < all.length; i++) {\n      const a = all[i];\n      if (a.kind === \"piece\" && (a.l < MARGIN - 1 || a.t < MARGIN - 1 || a.r > WIDTH - MARGIN + 1 || a.b > HEIGHT - MARGIN + 1)) problems.push(`scene ${scene.key}: \"${a.name}\" leaves the ${MARGIN}px margin`);\n      for (let j = i + 1; j < all.length; j++) {\n        const b = all[j];\n        if (a.kind === \"headline\" && b.kind === \"headline\") continue;\n        const d = gap(a, b);\n        if (d < 12) problems.push(`scene ${scene.key}: \"${a.name}\" and \"${b.name}\" ${d < 0 ? \"overlap\" : `are ${Math.round(d)}px apart`}`);\n      }\n    }\n  }\n  console.log(`${scenes.length} scenes checked, ${problems.length} layout problems`);\n}\nproblems.slice(0, 20).forEach((p) => console.log(`  ${p}`));\nawait browser.close();\nserver.close();\nif (problems.length) process.exit(1);\n",
  "playbooks/launch-videos/kit/scripts/audit/sound.mjs": "// Measures the mix, since nobody here can listen to it: integrated loudness about -16 LUFS, true peak at or under\n// -1.5 dBFS, and the same level in both ears for every shot. Usage: node scripts/audit/sound.mjs\nimport { join } from \"node:path\";\nimport { SHOTS } from \"../../edit/timeline.js\";\nimport { OUT } from \"../lib/config.mjs\";\nimport { channelLevel, loudness } from \"../lib/ffmpeg.mjs\";\n\nconst mix = join(OUT, \"mix.wav\");\nconst { lufs, peak } = loudness(mix);\nconst problems = [];\nif (Math.abs(lufs + 16) > 1) problems.push(`loudness ${lufs.toFixed(1)} LUFS (want -16)`);\nif (peak > -1.5) problems.push(`true peak ${peak.toFixed(1)} dBFS (want ≤ -1.5)`);\nfor (const shot of SHOTS) {\n  const [l, r] = [channelLevel(mix, \"c0\", shot.at, shot.len), channelLevel(mix, \"c1\", shot.at, shot.len)];\n  const ok = Math.abs(l - r) <= 1;\n  if (!ok) problems.push(`${shot.id}: left ${l.toFixed(1)} dB, right ${r.toFixed(1)} dB`);\n  console.log(`${shot.id}: L ${l.toFixed(1)} dB, R ${r.toFixed(1)} dB${ok ? \"\" : \"  UNEVEN\"}`);\n}\nconsole.log(`mix: ${lufs.toFixed(1)} LUFS, true peak ${peak.toFixed(1)} dBFS${problems.length ? `\\nproblems: ${problems.join(\"; \")}` : \", all checks pass\"}`);\nif (problems.length) process.exit(1);\n",
  "playbooks/launch-videos/kit/scripts/audit/stillness.mjs": "// The jitter check. For every hold (a headline, a glass scene, a still UI camera, the settled end card) it draws six\n// consecutive frames alternating across three browser pages with different histories (the worst case of a real\n// render) and requires them to be pixel-identical. Footage is hidden, since it moves by design.\n// Usage: node scripts/audit/stillness.mjs\nimport { chromium } from \"playwright-core\";\nimport { createHash } from \"node:crypto\";\nimport { FPS, HEADLINES, SHOT, SHOTS, TOTAL } from \"../../edit/timeline.js\";\nimport { sceneWindows } from \"../../page/overlays.js\";\nimport { endSettled } from \"../../page/end-card.js\";\nimport { launchOptions } from \"../lib/config.mjs\";\nimport { openFramePage } from \"../lib/browser.mjs\";\nimport { startServer } from \"../lib/server.mjs\";\n\nconst holds = [];\n// Never past the last frame: a headline or card that holds to the end is checked up to it.\nconst add = (name, t0, t1, hide) => { const end = Math.min(t1, TOTAL - 1 / FPS); if (end - t0 > 7 / FPS) holds.push({ name, t: t0, hide }); };\nfor (const hl of HEADLINES) {\n  const exit = Math.min(0.9, Math.max(0.55, hl.end - hl.at - 1.4));\n  add(`headline \"${hl.lines.join(\" / \")}\"`, hl.at + 1.15 + 0.1 * hl.lines.length, hl.end - exit - 0.1, [\"base\", \"overlays\", \"stage\", \"cursor\"]);\n}\nfor (const scene of sceneWindows()) {\n  // Pieces that animate by design (a waveform) are skipped; counters and switches declare when they stop (`still`).\n  if (scene.loop) continue;\n  add(`scene ${scene.key}`, scene.settled, Math.min(scene.leave, SHOT[scene.shot].end) - 0.3, [\"base\", \"heads\", \"stage\", \"cursor\"]);\n}\nfor (const shot of SHOTS.filter((s) => s.kind === \"ui\")) {\n  // Busy while the camera or cursor moves, a click ripples, or the screen changes; still in between.\n  const busy = [\n    ...(shot.camera ?? []).filter((k) => k.at > 0 || k.target).map((k) => [k.at, k.at + (k.dur ?? 1.3)]),\n    ...(shot.cursor ?? []).map((k) => [k.at, k.at + (k.click ? 0.5 : k.dur ?? 0.9)]),\n    ...(shot.images ?? []).filter((i) => i.at > 0).map((i) => [i.at - 0.01, i.at + 0.01]),\n  ].sort((a, b) => a[0] - b[0]);\n  let from = 0;\n  for (const [a, b] of [...busy, [shot.len, shot.len]]) {\n    add(`ui ${shot.id} ${from.toFixed(1)}-${a.toFixed(1)}s`, shot.at + from + 0.05, shot.at + a - 0.05, [\"overlays\", \"heads\", \"stage\"]);\n    from = Math.max(from, b);\n  }\n}\nfor (const shot of SHOTS.filter((s) => s.kind === \"end\")) add(\"end card\", shot.at + endSettled(), shot.end - 0.1, [\"base\", \"heads\", \"overlays\", \"cursor\"]);\n\nconst server = await startServer();\nconst browser = await chromium.launch(launchOptions());\nconst pages = [];\nfor (let i = 0; i < 3; i++) pages.push(await openFramePage(browser, server, 1));\nconst shot = async (page, t, hide) => {\n  await page.only(hide);\n  await page.draw(t);\n  return createHash(\"sha1\").update(await page.capture(\"png\")).digest(\"hex\").slice(0, 8);\n};\nlet moving = 0;\nfor (const hold of holds) {\n  // Give each page a different history before the hold.\n  for (let k = 0; k < pages.length; k++) await shot(pages[k], Math.max(0, hold.t - 0.4 - k * 0.37), hold.hide);\n  const hashes = [];\n  for (let i = 0; i < 6; i++) hashes.push(await shot(pages[i % 3], hold.t + i / FPS, hold.hide));\n  const still = new Set(hashes).size === 1;\n  if (!still) moving++;\n  console.log(`${still ? \"still \" : \"MOVES \"} ${hold.name} at ${hold.t.toFixed(2)}s ${still ? \"\" : hashes.join(\" \")}`);\n}\nawait browser.close();\nserver.close();\nconsole.log(`${holds.length} holds checked, ${moving} moving`);\nif (moving) process.exit(1);\n",
  "playbooks/launch-videos/kit/scripts/audit/torn-frames.mjs": "// Checks the encoded video: it has exactly as many frames as the timeline, and no torn or flashed frame (a frame\n// whose bottom band jumps away from both neighbours while they agree). Real cuts come from the timeline.\n// Usage: node scripts/audit/torn-frames.mjs [--video output/video-1x.mp4]\nimport { spawnSync } from \"node:child_process\";\nimport { join } from \"node:path\";\nimport { CUTS, FPS, FRAMES } from \"../../edit/timeline.js\";\nimport { arg, FF, OUT } from \"../lib/config.mjs\";\n\nconst video = arg(\"video\", join(OUT, \"video-1x.mp4\"));\nconst W = 64, H = 6, N = W * H;\nconst raw = spawnSync(FF, [\"-v\", \"error\", \"-i\", video, \"-vf\", `crop=iw:ih*0.1:0:ih*0.9,scale=${W}:${H},format=gray`, \"-f\", \"rawvideo\", \"-\"], { maxBuffer: 1 << 30 }).stdout;\nconst frames = Array.from({ length: Math.floor(raw.length / N) }, (_, i) => raw.subarray(i * N, (i + 1) * N));\nconst diff = (a, b) => a.reduce((sum, v, i) => sum + Math.abs(v - b[i]), 0) / N;\nconst torn = [];\nfor (let i = 1; i < frames.length - 3; i++) {\n  const t = i / FPS;\n  if (CUTS.some((c) => Math.abs(t - c) < 0.2)) continue;\n  for (const k of i >= 3 ? [1, 3] : [1]) {\n    if (diff(frames[i], frames[i - k]) > 12 && diff(frames[i], frames[i + k]) > 12 && diff(frames[i - k], frames[i + k]) < 6) { torn.push(`${i} (${t.toFixed(2)}s)`); break; }\n  }\n}\nconst complete = frames.length === FRAMES;\nconsole.log(`${frames.length} of ${FRAMES} frames, ${torn.length} torn${torn.length ? `: ${torn.slice(0, 20).join(\", \")}` : \"\"}`);\nif (torn.length || !complete) process.exit(1);\n",
  "playbooks/launch-videos/kit/scripts/audit/words.mjs": "// The clipped-word check, for any video with cuts. Every word of a clip's transcript that survives the cuts must\n// still be heard, in order, in the finished audio. A cut that clips a quietly trailing word (\"easy\") shows up here.\n// Transcribe output/mix.wav with the same tool you used for the clips (see the transcribe step) and save it as\n// media/words/final.json, then run: node scripts/audit/words.mjs\nimport { existsSync, readFileSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { SHOTS, kept } from \"../../edit/timeline.js\";\nimport { fail, MEDIA } from \"../lib/config.mjs\";\n\nconst read = (file) => {\n  const data = JSON.parse(readFileSync(file, \"utf8\"));\n  const list = Array.isArray(data) ? data : data.words ?? (data.segments ?? []).flatMap((s) => s.words ?? []);\n  return list.filter((w) => (w.type ?? \"word\") === \"word\").map((w) => ({ t: String(w.text ?? w.word ?? \"\"), s: Number(w.start), e: Number(w.end) }));\n};\nconst norm = (w) => w.toLowerCase().replace(/[^a-z0-9]/g, \"\");\nconst final = join(MEDIA, \"words\", \"final.json\");\nif (!existsSync(final)) fail(`Transcribe output/mix.wav and save it as ${final} first.`);\nconst expected = SHOTS.filter((shot) => shot.kind === \"clip\" && !shot.mute && existsSync(join(MEDIA, \"words\", `${shot.id}.json`)))\n  .flatMap((shot) => read(join(MEDIA, \"words\", `${shot.id}.json`)).filter((w) => kept(shot.id, (w.s + w.e) / 2)).map((w) => norm(w.t)))\n  .filter(Boolean);\nconst heard = read(final).map((w) => norm(w.t)).filter(Boolean);\nconst missing = [];\nlet j = 0;\nfor (const word of expected) {\n  const k = heard.indexOf(word, j);\n  if (k < 0) missing.push(word);\n  else j = k + 1;\n}\nconsole.log(`${expected.length - missing.length} of ${expected.length} kept words heard in the finished audio`);\nif (missing.length) { console.log(`missing after the cuts: ${missing.join(\" \")}`); process.exit(1); }\n",
  "playbooks/launch-videos/kit/scripts/capture.mjs": "// Captures the real product's screens for UI shots: each state in edit/capture.js at 2× pixels, plus the boxes of its\n// targets for the camera and cursor. Every run starts from nothing, so an old capture is never reused.\n// Usage: node scripts/capture.mjs                 capture every state\n//        node scripts/capture.mjs --login <url>   open Chrome so the user signs in; saves media/auth.json\nimport { chromium } from \"playwright-core\";\nimport { existsSync, mkdirSync, rmSync, writeFileSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { VIEWPORT, CAPTURES } from \"../edit/capture.js\";\nimport { arg, fail, launchOptions, MEDIA, OUT } from \"./lib/config.mjs\";\n\nconst auth = join(MEDIA, \"auth.json\");\nconst login = arg(\"login\");\nif (login) {\n  // The user signs in themselves; their password never passes through the agent.\n  mkdirSync(MEDIA, { recursive: true });\n  const browser = await chromium.launch(launchOptions({ headless: false }));\n  const context = await browser.newContext({ viewport: VIEWPORT });\n  await (await context.newPage()).goto(login);\n  console.log(\"Sign in in the Chrome window, then press Enter here.\");\n  await new Promise((r) => process.stdin.once(\"data\", r));\n  await context.storageState({ path: auth });\n  await browser.close();\n  console.log(`Saved the session to ${auth} (never commit it).`);\n  process.exit(0);\n}\nif (!CAPTURES.length) fail(\"edit/capture.js lists no captures.\");\nconst dir = join(OUT, \"ui\");\nrmSync(dir, { recursive: true, force: true });\nmkdirSync(dir, { recursive: true });\nconst browser = await chromium.launch(launchOptions());\nconst context = await browser.newContext({ viewport: VIEWPORT, deviceScaleFactor: 2, reducedMotion: \"reduce\", ...(existsSync(auth) ? { storageState: auth } : {}) });\nconst captures = {};\nfor (const capture of CAPTURES) {\n  const page = await context.newPage();\n  await page.goto(capture.url, { waitUntil: \"networkidle\" });\n  for (const action of capture.actions ?? []) {\n    if (action.click) await page.locator(action.click).first().click();\n    else if (action.hover) await page.locator(action.hover).first().hover();\n    else if (action.fill) await page.locator(action.fill[0]).first().fill(action.fill[1]);\n    else if (action.press) await page.keyboard.press(action.press);\n    else if (action.waitFor) await page.locator(action.waitFor).first().waitFor();\n    else if (action.wait) await page.waitForTimeout(action.wait);\n    else if (action.scroll) await page.mouse.wheel(action.scroll[0], action.scroll[1]);\n    else if (action.goto) await page.goto(action.goto, { waitUntil: \"networkidle\" });\n    else fail(`${capture.name}: unknown action ${JSON.stringify(action)}`);\n  }\n  if (capture.waitFor) await page.locator(capture.waitFor).first().waitFor();\n  await page.addStyleTag({ content: \"*, *::before, *::after { caret-color: transparent !important; transition: none !important; animation: none !important; }\" });\n  await page.evaluate(() => document.fonts.ready);\n  await page.mouse.move(-10, -10);\n  await page.waitForTimeout(300);\n  const image = `${capture.name}.png`;\n  await page.screenshot({ path: join(dir, image), animations: \"disabled\" });\n  const targets = {};\n  for (const [key, selector] of Object.entries(capture.targets ?? {})) {\n    const box = await page.locator(selector).first().boundingBox();\n    if (!box) fail(`${capture.name}: target \"${key}\" (${selector}) is not on screen.`);\n    targets[key] = box;\n  }\n  captures[capture.name] = { image, url: page.url(), targets };\n  await page.close();\n  console.log(`${capture.name}: ${Object.keys(targets).length} targets`);\n}\nawait browser.close();\nwriteFileSync(join(dir, \"manifest.json\"), JSON.stringify({ stamp: JSON.stringify({ VIEWPORT, CAPTURES }), viewport: VIEWPORT, captures }, null, 2));\nconsole.log(`${CAPTURES.length} states captured in ${dir}. Look at every image before using it: no real customer data.`);\n",
  "playbooks/launch-videos/kit/scripts/encode.mjs": "// Encodes the rendered frames and output/mix.wav into the video. Refuses to encode a frame sequence with gaps.\n// Usage: node scripts/encode.mjs [--scale 0.5|1|2] [--out output/video-1x.mp4]\nimport { existsSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { FPS, FRAMES, TOTAL } from \"../edit/timeline.js\";\nimport { arg, fail, OUT, pad, rate } from \"./lib/config.mjs\";\nimport { ffmpeg } from \"./lib/ffmpeg.mjs\";\n\nconst scale = arg(\"scale\", \"1\"), dir = join(OUT, \"frames\", scale), out = arg(\"out\", join(OUT, `video-${scale}x.mp4`));\nconst missing = Array.from({ length: FRAMES }, (_, f) => f).filter((f) => !existsSync(join(dir, `f${pad(f)}.jpg`)));\nif (missing.length) fail(`${missing.length} of ${FRAMES} frames are missing (first: ${missing[0]}). Run node scripts/render.mjs --scale ${scale}.`);\nif (!existsSync(join(OUT, \"mix.wav\"))) fail(\"No output/mix.wav. Run node scripts/mix.mjs first.\");\nconst started = Date.now();\nawait ffmpeg([\"-framerate\", rate(FPS), \"-i\", join(dir, \"f%06d.jpg\"), \"-i\", join(OUT, \"mix.wav\"), \"-map\", \"0:v\", \"-map\", \"1:a\",\n  \"-c:v\", \"libx264\", \"-preset\", Number(scale) >= 2 ? \"slow\" : \"medium\", \"-crf\", Number(scale) >= 2 ? \"15\" : \"16\", \"-tune\", \"film\",\n  \"-pix_fmt\", \"yuv420p\", \"-colorspace\", \"bt709\", \"-color_primaries\", \"bt709\", \"-color_trc\", \"bt709\",\n  \"-c:a\", \"aac\", \"-b:a\", \"256k\", \"-movflags\", \"+faststart\", \"-t\", TOTAL.toFixed(3), out]);\nconsole.log(`encoded ${FRAMES} frames in ${((Date.now() - started) / 1000).toFixed(1)}s → ${out}`);\n",
  "playbooks/launch-videos/kit/scripts/lib/browser.mjs": "// Opens the frame page pinned to the exact canvas and draws frames deterministically. Shared by render and audits.\nimport { WIDTH, HEIGHT } from \"../../edit/timeline.js\";\n\n/**\n * scale: 0.5 to review, 1 for the master size, 2 for 4K from a 1920×1080 layout. Without the metrics override the\n * capture follows the headless window, not the canvas, and cuts the bottom off.\n */\nexport async function openFramePage(browser, server, scale = 1) {\n  const page = await browser.newPage({ viewport: { width: WIDTH, height: HEIGHT }, deviceScaleFactor: scale });\n  let error = null;\n  page.on(\"pageerror\", (e) => { error = e; });\n  await page.goto(`${server.url}/page/index.html?scale=${scale}`);\n  await page.waitForFunction(() => typeof window.renderFrame === \"function\", null, { timeout: 30_000 }).catch(() => {});\n  if (error) throw error;\n  if (!(await page.evaluate(() => typeof window.renderFrame === \"function\"))) {\n    throw new Error(\"The frame page did not load. Check edit/*.js for a syntax error, and run the capture first for UI shots.\");\n  }\n  const cdp = await page.context().newCDPSession(page);\n  await cdp.send(\"Emulation.setDeviceMetricsOverride\", { width: WIDTH, height: HEIGHT, deviceScaleFactor: scale, mobile: false });\n  const draw = async (t) => {\n    // Build the frame, wait for every image and font, then for two animation frames so the new frame is on screen.\n    await page.evaluate(async (x) => {\n      await window.renderFrame(x);\n      await window.settle();\n      await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));\n    }, t);\n    if (error) throw error;\n  };\n  const capture = async (format = \"jpeg\") => {\n    const { data } = await cdp.send(\"Page.captureScreenshot\", {\n      format, ...(format === \"jpeg\" ? { quality: 95 } : {}), optimizeForSpeed: true, clip: { x: 0, y: 0, width: WIDTH, height: HEIGHT, scale: 1 },\n    });\n    return Buffer.from(data, \"base64\");\n  };\n  // The first captures after load can come from a frame laid out before the override settled (a torn band at the\n  // bottom). Draw and discard two frames before any real capture.\n  const warm = async (t) => {\n    for (const x of [t, t + 0.04]) { await draw(x); await capture(); }\n  };\n  // Hide some layers (audits look at one layer at a time).\n  const only = (hidden) => page.evaluate((names) => {\n    for (const [name, el] of Object.entries(window.layers)) el.style.visibility = names.includes(name) ? \"hidden\" : \"\";\n  }, hidden);\n  return { page, draw, capture, warm, only };\n}\n",
  "playbooks/launch-videos/kit/scripts/lib/config.mjs": "// Where the pipeline reads and writes, and the small helpers every script shares. Runs on Node 20+ or Bun.\nimport { dirname, join, resolve } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\nexport const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), \"../..\");\n// Source media (clips, narration, music, brand files, word timings). Never committed.\nexport const MEDIA = join(ROOT, \"media\");\n// Everything generated. Never committed, always rebuilt from media/ and edit/.\nexport const OUT = join(ROOT, \"output\");\nexport const FF = process.env.FFMPEG ?? \"ffmpeg\";\n// The installed Google Chrome (Playwright's \"chrome\" channel), or CHROME=<path>.\nexport const launchOptions = (extra = {}) => ({\n  ...(process.env.CHROME ? { executablePath: process.env.CHROME } : { channel: \"chrome\" }),\n  args: [\"--font-render-hinting=none\", \"--disable-lcd-text\", \"--hide-scrollbars\"],\n  ...extra,\n});\nexport const arg = (name, fallback) => {\n  const i = process.argv.indexOf(`--${name}`);\n  return i >= 0 && process.argv[i + 1] !== undefined ? process.argv[i + 1] : fallback;\n};\nexport const flag = (name) => process.argv.includes(`--${name}`);\nexport const pad = (n) => String(n).padStart(6, \"0\");\n// ffmpeg wants exact rates: 23.976 is 24000/1001, not a rounded decimal.\nexport const rate = (fps) => [24, 25, 30, 48, 50, 60].map((n) => [n * 1000 / 1001, `${n * 1000}/1001`]).find(([v]) => Math.abs(v - fps) < 1e-6)?.[1] ?? String(fps);\nexport const fail = (message) => { console.error(message); process.exit(1); };\n",
  "playbooks/launch-videos/kit/scripts/lib/ffmpeg.mjs": "// Thin ffmpeg helpers. You cannot listen to audio, so every claim about it comes from these measurements.\nimport { spawn, spawnSync } from \"node:child_process\";\nimport { FF } from \"./config.mjs\";\n\nexport const ffmpeg = (args) => new Promise((ok, fail) => {\n  const run = spawn(FF, [\"-y\", \"-hide_banner\", \"-loglevel\", \"error\", ...args], { stdio: [\"ignore\", \"inherit\", \"inherit\"] });\n  run.on(\"error\", fail);\n  run.on(\"exit\", (code) => (code === 0 ? ok() : fail(new Error(`ffmpeg exited ${code} writing ${args.at(-1)}`))));\n});\nexport const ffmpegSync = (args) => {\n  const run = spawnSync(FF, [\"-v\", \"error\", \"-y\", ...args]);\n  if (run.status !== 0) throw new Error(run.stderr?.toString() || `ffmpeg failed writing ${args.at(-1)}`);\n};\nconst analyse = (file, af) => spawnSync(FF, [\"-hide_banner\", \"-nostats\", \"-i\", file, \"-af\", af, \"-f\", \"null\", \"-\"], { encoding: \"utf8\", maxBuffer: 1 << 26 }).stderr;\n\n/** Duration, frame rate and audio channels, read from ffmpeg's own description of the file. */\nexport function probe(file) {\n  const text = spawnSync(FF, [\"-hide_banner\", \"-i\", file], { encoding: \"utf8\" }).stderr;\n  const [, h, m, s] = text.match(/Duration: (\\d+):(\\d+):([\\d.]+)/) ?? [];\n  const audio = text.match(/Audio: .*?, (\\d+) Hz, ([^,]+)/);\n  return {\n    duration: h ? Number(h) * 3600 + Number(m) * 60 + Number(s) : 0,\n    fps: Number(text.match(/, ([\\d.]+) fps/)?.[1] ?? 0),\n    audio: Boolean(audio),\n    channels: audio ? (/mono/.test(audio[2]) ? 1 : 2) : 0,\n  };\n}\n/** Integrated loudness (LUFS) and true peak (dBFS), optionally after a filter such as a pan. */\nexport function loudness(file, af = \"\") {\n  const text = analyse(file, `${af ? `${af},` : \"\"}ebur128=peak=true`);\n  const integrated = text.match(/I:\\s+(-?[\\d.]+) LUFS/g)?.at(-1)?.match(/-?[\\d.]+/)?.[0];\n  const peak = text.match(/Peak:\\s+(-?[\\d.inf]+) dBFS/g)?.at(-1)?.match(/-?[\\d.]+|-inf/)?.[0];\n  if (integrated === undefined) throw new Error(`Could not measure loudness of ${file}`);\n  return { lufs: Number(integrated), peak: peak === \"-inf\" ? -Infinity : Number(peak) };\n}\n/** Mean level of one channel (c0 left, c1 right) in dB, optionally for a section. */\nexport function channelLevel(file, channel, start = 0, length = 0) {\n  const section = length > 0 ? `atrim=${start}:${start + length},` : \"\";\n  return Number(analyse(file, `${section}pan=mono|c0=${channel},volumedetect`).match(/mean_volume: (-?[\\d.]+) dB/)?.[1] ?? -91);\n}\n/**\n * Cameras often record the lav on one channel only, which plays the voice in one ear. Returns a pan that puts the\n * voice in both ears: the live channel copied to left and right, or a balanced downmix when both carry signal.\n */\nexport function centerVoice(file) {\n  if (probe(file).channels === 1) return \"pan=stereo|c0=c0|c1=c0\";\n  const [l, r] = [channelLevel(file, \"c0\"), channelLevel(file, \"c1\")];\n  if (l - r > 12) return \"pan=stereo|c0=c0|c1=c0\";\n  if (r - l > 12) return \"pan=stereo|c0=c1|c1=c1\";\n  return \"pan=stereo|c0=0.5*c0+0.5*c1|c1=0.5*c0+0.5*c1\";\n}\n",
  "playbooks/launch-videos/kit/scripts/lib/head-line.mjs": "// The top of the speaker's head on every frame of a reel, in layout pixels, so glass can stay above it. Walks each\n// column of the central band down from the top, following the background colour as it drifts (sky gradients, walls),\n// and stops at the first abrupt change. The head line is the 3rd-highest column, so one stray pixel never moves it.\n// A fixed line was wrong both ways: a real hairline moved between 564px and 664px.\nimport { spawnSync } from \"node:child_process\";\nimport { FF } from \"./config.mjs\";\n\nexport function headLines(framesDir, width, height) {\n  const W = Math.round(width / 4), H = Math.round(height / 4), bytes = W * H * 3, X0 = Math.round(W * 0.26), X1 = Math.round(W * 0.74);\n  const raw = spawnSync(FF, [\"-v\", \"error\", \"-i\", `${framesDir}/f%06d.jpg`, \"-vf\", `scale=${W}:${H}`, \"-f\", \"rawvideo\", \"-pix_fmt\", \"rgb24\", \"-\"], { maxBuffer: 2 ** 31 }).stdout;\n  const lines = [];\n  for (let o = 0; o + bytes <= raw.length; o += bytes) {\n    const rgb = raw.subarray(o, o + bytes), tops = [];\n    for (let x = X0; x < X1; x++) {\n      const bg = [0, 0, 0];\n      for (let y = 0; y < 3; y++) for (let c = 0; c < 3; c++) bg[c] += rgb[(y * W + x) * 3 + c] / 3;\n      let hit = H, streak = 0;\n      for (let y = 3; y < H; y++) {\n        const i = (y * W + x) * 3, d = Math.abs(rgb[i] - bg[0]) + Math.abs(rgb[i + 1] - bg[1]) + Math.abs(rgb[i + 2] - bg[2]);\n        if (d > 60) { if (++streak === 2) { hit = y - 1; break; } continue; }\n        streak = 0;\n        for (let c = 0; c < 3; c++) bg[c] = bg[c] * 0.8 + rgb[i + c] * 0.2;\n      }\n      tops.push(hit);\n    }\n    lines.push(tops.sort((a, b) => a - b)[2] * 4);\n  }\n  return lines;\n}\n",
  "playbooks/launch-videos/kit/scripts/lib/server.mjs": "// Serves this folder to the frame page on 127.0.0.1, so it can read edit/, page/, media/ and output/.\nimport { createReadStream, existsSync, statSync } from \"node:fs\";\nimport { createServer } from \"node:http\";\nimport { extname, join, normalize, sep } from \"node:path\";\nimport { ROOT } from \"./config.mjs\";\n\nconst TYPES = {\n  \".html\": \"text/html\", \".js\": \"text/javascript\", \".mjs\": \"text/javascript\", \".css\": \"text/css\", \".json\": \"application/json\",\n  \".svg\": \"image/svg+xml\", \".png\": \"image/png\", \".jpg\": \"image/jpeg\", \".jpeg\": \"image/jpeg\", \".webp\": \"image/webp\",\n  \".woff2\": \"font/woff2\", \".woff\": \"font/woff\", \".ttf\": \"font/ttf\", \".otf\": \"font/otf\",\n};\n\nexport function startServer() {\n  const server = createServer((req, res) => {\n    const file = join(ROOT, normalize(decodeURIComponent(new URL(req.url ?? \"/\", \"http://local\").pathname)));\n    if (!file.startsWith(ROOT + sep) || !existsSync(file) || !statSync(file).isFile()) return void res.writeHead(404).end();\n    res.writeHead(200, { \"content-type\": TYPES[extname(file).toLowerCase()] ?? \"application/octet-stream\" });\n    createReadStream(file).pipe(res);\n  });\n  return new Promise((ok) => server.listen(0, \"127.0.0.1\", () => ok({ url: `http://127.0.0.1:${server.address().port}`, close: () => server.close() })));\n}\n",
  "playbooks/launch-videos/kit/scripts/lib/stamp.mjs": "// What a footage extraction was made from. The renderer refuses frames made for a different edit or size.\nimport { FPS, SHOTS, WIDTH, HEIGHT } from \"../../edit/timeline.js\";\n\nexport const footageShots = () => SHOTS.filter((shot) => shot.kind === \"clip\" || (shot.kind === \"end\" && shot.file));\nexport const footageStamp = (scale) => JSON.stringify(footageShots().map(({ id, file, ranges, len }) => ({\n  id, file, ranges, len, fps: FPS, w: Math.round(WIDTH * scale), h: Math.round(HEIGHT * scale),\n})));\n",
  "playbooks/launch-videos/kit/scripts/mix.mjs": "// Builds the soundtrack from the one timeline: the camera's own voice (centred in both ears, level-matched, nothing\n// else done to it), generated narration, the end clip's sound kept low, the whooshes, and music only when the edit\n// asks for it, ducked under every phrase. Then one static gain to -16 LUFS and a peak limiter, so nothing pumps.\n// Writes output/mix.wav. Usage: node scripts/mix.mjs\nimport { existsSync, readFileSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { SHOTS, NARRATION, MUSIC, TOTAL } from \"../edit/timeline.js\";\nimport { SPEECH } from \"../edit/speech.js\";\nimport { fail, MEDIA, OUT } from \"./lib/config.mjs\";\nimport { centerVoice, ffmpeg, loudness } from \"./lib/ffmpeg.mjs\";\n\nconst inputs = [], filters = [], labels = [];\nconst add = (file, chain) => {\n  const i = inputs.length / 2;\n  inputs.push(\"-i\", file);\n  filters.push(`[${i}:a]aresample=48000,${chain}[a${i}]`);\n  labels.push(`[a${i}]`);\n};\nconst delay = (t) => `adelay=${Math.round(t * 1000)}:all=1`;\n// One static gain to a target, measured after the pan (copying a mono voice to both ears makes it louder).\nconst level = (file, pan, target) => (target - loudness(file, pan).lufs).toFixed(2);\n\nfor (const shot of SHOTS) {\n  const file = join(OUT, \"audio\", `${shot.id}.wav`);\n  if (!existsSync(file) || shot.mute) continue;\n  const pan = centerVoice(file);\n  if (shot.kind === \"clip\") {\n    add(file, `${pan},afade=t=in:d=0.01,afade=t=out:st=${(shot.len - 0.04).toFixed(3)}:d=0.04,volume=${level(file, pan, -17)}dB,${delay(shot.at)}`);\n  } else if (shot.kind === \"end\") {\n    // The end clip's own sound (birds, air), present but low.\n    add(file, `${pan},afade=t=in:d=0.8:curve=qsin,afade=t=out:st=${(shot.len - 1.4).toFixed(3)}:d=1.4:curve=qsin,volume=${level(file, pan, -32)}dB,${delay(shot.at)}`);\n  }\n}\nfor (const line of NARRATION) {\n  const file = join(MEDIA, \"narration\", `${line.file}.wav`);\n  if (!existsSync(file)) fail(`Missing narration ${file}. Generate it (see the narrate step) or remove it from edit/timeline.js.`);\n  const pan = centerVoice(file);\n  add(file, `${pan},volume=${level(file, pan, -17)}dB,${delay(line.at)}`);\n}\nconst cues = existsSync(join(OUT, \"sfx/cues.json\")) ? JSON.parse(readFileSync(join(OUT, \"sfx/cues.json\"), \"utf8\")) : [];\nfor (const t of cues) add(join(OUT, \"sfx/whoosh.wav\"), delay(t));\nif (MUSIC) {\n  // Music sits about 10 dB under the voice in the gaps and about 17 dB under while someone speaks (a volume\n  // expression over time with a 0.3s ramp down and 0.5s back up; a sidechain compressor pumps).\n  const file = join(MEDIA, MUSIC.file ?? \"music.wav\");\n  if (!existsSync(file)) fail(`Missing music ${file}.`);\n  const spans = [];\n  for (const p of SPEECH) { const last = spans.at(-1); if (last && p.s - last[1] < 0.7) last[1] = p.e; else spans.push([p.s, p.e]); }\n  const speaking = spans.length ? `min(1,${spans.map(([s, e]) => `clip((t-${(s - 0.3).toFixed(2)})/0.3,0,1)*clip((${(e + 0.5).toFixed(2)}-t)/0.5,0,1)`).join(\"+\")})` : \"0\";\n  const start = MUSIC.at ?? 0, from = MUSIC.from ?? 0;\n  add(file, `atrim=${from}:${from + TOTAL - start},asetpts=PTS-STARTPTS,volume=${level(file, \"\", -27)}dB,afade=t=out:st=${(TOTAL - start - 2).toFixed(2)}:d=2:curve=qsin,${delay(start)},volume='1-0.55*${speaking}':eval=frame`);\n}\nif (!labels.length) fail(\"Nothing to mix: no camera audio, narration, whooshes or music.\");\nconst premix = join(OUT, \"premix.wav\"), mix = join(OUT, \"mix.wav\");\nawait ffmpeg([...inputs, \"-filter_complex\", `${filters.join(\";\")};${labels.join(\"\")}amix=inputs=${labels.length}:normalize=0:duration=longest:dropout_transition=0[out]`,\n  \"-map\", \"[out]\", \"-t\", TOTAL.toFixed(3), \"-ac\", \"2\", \"-c:a\", \"pcm_s24le\", premix]);\nconst measured = loudness(premix).lufs;\nawait ffmpeg([\"-i\", premix, \"-af\", `volume=${(-16 - measured).toFixed(2)}dB,alimiter=limit=0.75:attack=1:release=60:level=disabled`, \"-c:a\", \"pcm_s24le\", mix]);\nconst final = loudness(mix);\nconsole.log(`mix ${measured.toFixed(1)} LUFS → ${final.lufs.toFixed(1)} LUFS, true peak ${final.peak.toFixed(1)} dBFS (${labels.length} sources)`);\n",
  "playbooks/launch-videos/kit/scripts/pauses.mjs": "// Finds where a clip may be cut, from the audio itself (word timings can be 0.35s off and merge words), and suggests\n// keep ranges for edit/timeline.js. Two thresholds over the speech band (300–3400 Hz): loud (noise floor + 13 dB)\n// finds pauses between phrases; silent (floor + 6 dB) bounds where a cut may fall. Word endings trail quietly, so a pause\n// is cut only if it lasts at least 0.8s loud to loud and holds at least 0.5s of true silence; the cut sits inside it.\n// Usage: node scripts/pauses.mjs <clip file in media/clips/>\nimport { spawnSync } from \"node:child_process\";\nimport { join } from \"node:path\";\nimport { FF, MEDIA, fail } from \"./lib/config.mjs\";\n\nconst file = process.argv[2];\nif (!file) fail(\"Usage: node scripts/pauses.mjs <clip file in media/clips/>\");\nconst STEP = 0.01;\nconst raw = spawnSync(FF, [\"-v\", \"error\", \"-i\", join(MEDIA, \"clips\", file), \"-vn\", \"-af\", \"pan=mono|c0=0.5*c0+0.5*c1,highpass=f=300:p=2,lowpass=f=3400\",\n  \"-ar\", \"16000\", \"-f\", \"s16le\", \"-\"], { maxBuffer: 2 ** 30 }).stdout;\nif (!raw?.length) fail(`No audio in media/clips/${file}.`);\nconst samples = new Int16Array(raw.buffer, raw.byteOffset, Math.floor(raw.byteLength / 2)), db = [];\nfor (let i = 0; i + 160 <= samples.length; i += 160) {\n  let e = 0;\n  for (let j = i; j < i + 160; j++) e += (samples[j] / 32768) ** 2;\n  db.push(10 * Math.log10(e / 160 + 1e-12));\n}\nconst floor = [...db].sort((a, b) => a - b)[Math.floor(db.length * 0.2)];\nconst peak = (i, r) => Math.max(...db.slice(Math.max(0, i - r), i + r + 1));\nconst runs = (flags) => {\n  const out = [];\n  for (let i = 0; i < flags.length;) {\n    if (!flags[i]) { i++; continue; }\n    let j = i;\n    while (j < flags.length && flags[j]) j++;\n    out.push([i * STEP, j * STEP]);\n    i = j;\n  }\n  return out;\n};\nconst speech = runs(db.map((_, i) => peak(i, 1) > floor + 13)).filter(([a, b]) => b - a >= 0.08);\nconst quiet = runs(db.map((_, i) => peak(i, 2) < floor + 6));\nconst gaps = speech.slice(1).map(([a], i) => [speech[i][1], a]);\nconst silenceIn = ([a, b]) => quiet.map(([x, y]) => [Math.max(a, x), Math.min(b, y)]).filter(([x, y]) => y > x).sort((p, q) => (q[1] - q[0]) - (p[1] - p[0]))[0];\nconst cuts = [], kept = [];\nfor (const gap of gaps) {\n  if (gap[1] - gap[0] < 0.8) continue;\n  const s = silenceIn(gap);\n  if (!s || s[1] - s[0] < 0.5) { kept.push(gap); continue; }\n  cuts.push([s[0] + 0.08, s[1]]);\n}\n// Start 0.07s before the first word; hold 0.4s after the last sound, so a reel loops cleanly.\nconst first = speech[0]?.[0] ?? 0, last = speech.at(-1)?.[1] ?? db.length * STEP;\nconst tail = quiet.find(([x, y]) => x >= last && y - x >= 0.2)?.[0] ?? last;\nconst keep = [];\nlet from = Math.max(0, first - 0.07);\nfor (const [a, b] of cuts) { keep.push([+from.toFixed(2), +a.toFixed(2)]); from = b; }\nkeep.push([+from.toFixed(2), +Math.min(db.length * STEP, tail + 0.4).toFixed(2)]);\nconst f2 = (v) => v.toFixed(2);\nconsole.log(`noise floor ${f2(floor)} dB; first word ${f2(first)}s; last sound ${f2(last)}s`);\nconsole.log(`pauses of 0.3s or more: ${gaps.filter(([a, b]) => b - a >= 0.3).map(([a, b]) => `${f2(a)}–${f2(b)}`).join(\", \") || \"none\"}`);\nfor (const g of kept) console.log(`  not cut ${f2(g[0])}–${f2(g[1])}: a word tail or breath, not enough true silence`);\nconsole.log(`suggested keep: ${JSON.stringify(keep)} (${f2(keep.reduce((n, [a, b]) => n + b - a, 0))}s)`);\n",
  "playbooks/launch-videos/kit/scripts/prepare.mjs": "// Turns the filmed clips into what the renderer and mixer read: one JPEG per output frame for every footage shot\n// (output/footage/<scale>/<shot>/), and each shot's own audio, cut on the same frames (output/audio/<shot>.wav).\n// Reels also get the speaker's head line on every frame (output/head/<shot>.json). Always rebuilt from scratch.\n// Usage: node scripts/prepare.mjs [--scale 0.5|1|2]\nimport { existsSync, mkdirSync, rmSync, writeFileSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { FPS, WIDTH, HEIGHT, LAYOUT } from \"../edit/timeline.js\";\nimport { arg, fail, MEDIA, OUT, rate } from \"./lib/config.mjs\";\nimport { ffmpegSync, probe } from \"./lib/ffmpeg.mjs\";\nimport { headLines } from \"./lib/head-line.mjs\";\nimport { footageShots, footageStamp } from \"./lib/stamp.mjs\";\n\nconst scale = Number(arg(\"scale\", \"1\"));\nconst [w, h] = [Math.round(WIDTH * scale), Math.round(HEIGHT * scale)];\nconst dir = join(OUT, \"footage\", String(scale));\nrmSync(dir, { recursive: true, force: true });\nfor (const folder of [\"audio\", \"head\"]) mkdirSync(join(OUT, folder), { recursive: true });\nfor (const shot of footageShots()) {\n  const file = join(MEDIA, \"clips\", shot.file);\n  if (!existsSync(file)) fail(`Missing ${file}. Put the clip in media/clips/ or fix the file name in edit/timeline.js.`);\n  const info = probe(file);\n  const end = Math.max(...shot.ranges.map((r) => r.to));\n  if (end > info.duration + 0.05) fail(`Shot \"${shot.id}\" runs to ${end.toFixed(2)}s but ${shot.file} is ${info.duration.toFixed(2)}s.`);\n  if (info.fps && Math.abs(info.fps - FPS) > 0.01) console.warn(`${shot.file} is ${info.fps} fps and the timeline is ${FPS.toFixed(3)}: frames are resampled to the timeline.`);\n  const out = join(dir, shot.id);\n  mkdirSync(out, { recursive: true });\n  // Picture: each kept range, numbered on from the last, so a cut is one frame to the next. Phones' rotation is\n  // applied by ffmpeg; a source of another shape is centre-cropped to fill the canvas.\n  let start = 0;\n  for (const r of shot.ranges) {\n    ffmpegSync([\"-ss\", String(r.from), \"-i\", file, \"-t\", (r.to - r.from).toFixed(3), \"-an\",\n      \"-vf\", `fps=${rate(FPS)},scale=${w}:${h}:force_original_aspect_ratio=increase:flags=lanczos,crop=${w}:${h},tpad=stop_mode=clone:stop=4`,\n      \"-frames:v\", String(r.frames), \"-q:v\", \"2\", \"-start_number\", String(start), join(out, \"f%06d.jpg\")]);\n    start += r.frames;\n  }\n  // Sound: the camera's own audio, untouched (no denoise, no EQ), cut at the same frames with 6ms fades at each join\n  // so the cuts never click. The mix centres and level-matches it.\n  if (info.audio) {\n    const parts = shot.ranges.map((r, i) => {\n      const len = r.frames / FPS;\n      return `[0:a]atrim=${r.from.toFixed(5)}:${(r.from + len).toFixed(5)},asetpts=PTS-STARTPTS,afade=t=in:d=0.006,afade=t=out:st=${(len - 0.006).toFixed(5)}:d=0.006[p${i}]`;\n    });\n    ffmpegSync([\"-i\", file, \"-filter_complex\", `${parts.join(\";\")};${parts.map((_, i) => `[p${i}]`).join(\"\")}concat=n=${parts.length}:v=0:a=1[a]`,\n      \"-map\", \"[a]\", \"-ar\", \"48000\", \"-c:a\", \"pcm_s24le\", join(OUT, \"audio\", `${shot.id}.wav`)]);\n  }\n  if (LAYOUT === \"reel\" && shot.kind === \"clip\") writeFileSync(join(OUT, \"head\", `${shot.id}.json`), JSON.stringify(headLines(out, WIDTH, HEIGHT)));\n  console.log(`${shot.id}: ${start} frames at ${w}×${h}, ${shot.ranges.length} range(s)${info.audio ? \", audio\" : \", no audio\"}`);\n}\nwriteFileSync(join(dir, \"stamp.json\"), footageStamp(scale));\nconsole.log(`${footageShots().length} footage shots prepared in ${dir}`);\n",
  "playbooks/launch-videos/kit/scripts/render.mjs": "// Captures every frame with headless Chrome. Renders split only at shot cuts: each shot is drawn start to finish by\n// one fresh browser, so a held frame never depends on what another page drew first. One shot at a time by default.\n// Usage: node scripts/render.mjs [--scale 0.5|1|2] [--from <s>] [--to <s>] [--jobs <n>]\nimport { chromium } from \"playwright-core\";\nimport { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { FPS, FRAMES, SHOTS } from \"../edit/timeline.js\";\nimport { CAPTURES, VIEWPORT } from \"../edit/capture.js\";\nimport { arg, fail, launchOptions, OUT, pad } from \"./lib/config.mjs\";\nimport { openFramePage } from \"./lib/browser.mjs\";\nimport { startServer } from \"./lib/server.mjs\";\nimport { footageShots, footageStamp } from \"./lib/stamp.mjs\";\n\nconst scale = Number(arg(\"scale\", \"1\")), jobs = Math.max(1, Number(arg(\"jobs\", \"1\")));\nconst first = Math.max(0, Math.round(Number(arg(\"from\", \"0\")) * FPS));\nconst last = Math.min(FRAMES - 1, arg(\"to\") === undefined ? FRAMES - 1 : Math.round(Number(arg(\"to\")) * FPS));\n\n// Never reuse old inputs: footage must be prepared for this exact edit, captures for this exact capture list.\nif (footageShots().length) {\n  const stamp = join(OUT, \"footage\", String(scale), \"stamp.json\");\n  if (!existsSync(stamp) || readFileSync(stamp, \"utf8\") !== footageStamp(scale)) fail(`The footage frames do not match edit/timeline.js. Run: node scripts/prepare.mjs --scale ${scale}`);\n}\nif (SHOTS.some((s) => s.kind === \"ui\")) {\n  const manifest = join(OUT, \"ui\", \"manifest.json\");\n  if (!existsSync(manifest) || JSON.parse(readFileSync(manifest, \"utf8\")).stamp !== JSON.stringify({ VIEWPORT, CAPTURES })) {\n    fail(\"The UI captures do not match edit/capture.js. Run: node scripts/capture.mjs\");\n  }\n}\nconst dir = join(OUT, \"frames\", String(scale));\nmkdirSync(dir, { recursive: true });\n// Clear the frames this run replaces, so a stale frame can never end up in the video.\nfor (const name of readdirSync(dir)) {\n  const f = Number(name.match(/^f(\\d+)\\.jpg$/)?.[1] ?? -1);\n  if (f >= first && f <= last) rmSync(join(dir, name));\n}\nconst chunks = SHOTS.map((shot) => {\n  const a = Math.max(first, Math.round(shot.at * FPS)), b = Math.min(last, Math.round(shot.end * FPS) - 1);\n  return { shot: shot.id, frames: b >= a ? Array.from({ length: b - a + 1 }, (_, i) => a + i) : [] };\n}).filter((c) => c.frames.length);\nconst server = await startServer();\nconst total = chunks.reduce((n, c) => n + c.frames.length, 0), started = Date.now();\nlet done = 0;\nconst queue = [...chunks];\nawait Promise.all(Array.from({ length: Math.min(jobs, chunks.length) }, async () => {\n  for (let chunk = queue.shift(); chunk; chunk = queue.shift()) {\n    const browser = await chromium.launch(launchOptions());\n    const frame = await openFramePage(browser, server, scale);\n    await frame.warm(chunk.frames[0] / FPS);\n    for (const f of chunk.frames) {\n      await frame.draw(f / FPS);\n      writeFileSync(join(dir, `f${pad(f)}.jpg`), await frame.capture(\"jpeg\"));\n      if (++done % 100 === 0) console.log(`${done}/${total} frames, ${((Date.now() - started) / done).toFixed(0)} ms each`);\n    }\n    await browser.close();\n  }\n}));\nserver.close();\nconsole.log(`rendered ${total} frames (${chunks.length} shots) to ${dir} in ${((Date.now() - started) / 1000).toFixed(1)}s`);\n",
  "playbooks/launch-videos/kit/scripts/sound-effects.mjs": "// One plain sound, synthesised, and cued from the animation timings so it can never drift from the picture: a soft\n// whoosh on the opening headline (a reel's hook) and as each glass scene enters. Ticks, pops, chimes, swells and a\n// whoosh on every headline were rejected as \"bells and whistles\"; add one only if the user asks.\n// Writes output/sfx/whoosh.wav and output/sfx/cues.json. Usage: node scripts/sound-effects.mjs\nimport { mkdirSync, writeFileSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { HEADLINES } from \"../edit/timeline.js\";\nimport { sceneWindows } from \"../page/overlays.js\";\nimport { OUT } from \"./lib/config.mjs\";\nimport { ffmpegSync } from \"./lib/ffmpeg.mjs\";\n\nconst dir = join(OUT, \"sfx\");\nmkdirSync(dir, { recursive: true });\n// Soft air: band-limited pink noise with a smooth swell and release, kept well under the voice.\nffmpegSync([\"-f\", \"lavfi\", \"-i\", \"anoisesrc=color=pink:duration=0.95:amplitude=0.7:seed=7\",\n  \"-af\", \"highpass=f=320,lowpass=f=2600,afade=t=in:d=0.45:curve=qsin,afade=t=out:st=0.45:d=0.5:curve=qsin,volume=0.32\",\n  \"-ac\", \"2\", \"-ar\", \"48000\", join(dir, \"whoosh.wav\")]);\nconst cues = [];\nconst push = (t) => { if (t >= 0 && !cues.some((c) => Math.abs(c - t) < 0.3)) cues.push(+t.toFixed(3)); };\nif (HEADLINES[0]) push(Math.max(0, HEADLINES[0].at - 0.08));\nfor (const scene of sceneWindows()) push(scene.enter - 0.08);\ncues.sort((a, b) => a - b);\nwriteFileSync(join(dir, \"cues.json\"), JSON.stringify(cues));\nconsole.log(`${cues.length} whooshes: ${cues.map((t) => t.toFixed(2)).join(\", \")}`);\n",
  "playbooks/launch-videos/kit/scripts/speech.mjs": "// Places every spoken phrase on the timeline from word timings, and writes edit/speech.js. Headlines, glass scenes\n// and the music ducking are all timed from it. Word timings live in media/words/: <shot id>.json for a clip (times\n// from the start of the source file), <file>.json for narration. Accepted shapes: ElevenLabs speech to text or forced\n// alignment ({ words: [{ text, start, end }] }), Whisper ({ segments: [{ words: [{ word, start, end }] }] }), or a\n// plain [{ text, start, end }]. Usage: node scripts/speech.mjs\nimport { existsSync, readFileSync, writeFileSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { SHOTS, NARRATION, kept, place } from \"../edit/timeline.js\";\nimport { MEDIA, ROOT } from \"./lib/config.mjs\";\n\nfunction words(file) {\n  const data = JSON.parse(readFileSync(file, \"utf8\"));\n  const list = Array.isArray(data) ? data : data.words ?? (data.segments ?? []).flatMap((s) => s.words ?? []);\n  return list.filter((w) => (w.type ?? \"word\") === \"word\")\n    .map((w) => ({ t: String(w.text ?? w.word ?? \"\").trim(), s: Number(w.start ?? w.start_time), e: Number(w.end ?? w.end_time) }))\n    .filter((w) => w.t && Number.isFinite(w.s) && Number.isFinite(w.e));\n}\n\n// A clip's words are on its source clock: words in a removed stretch are dropped, the rest move through the cuts.\nconst sources = [\n  ...SHOTS.filter((shot) => shot.kind === \"clip\" && !shot.mute).map((shot) => ({ file: `${shot.id}.json`, keep: (t) => kept(shot.id, t), at: (t) => place(shot.id, t) })),\n  ...NARRATION.map((line) => ({ file: `${line.file}.json`, keep: () => true, at: (t) => line.at + t })),\n];\nconst placed = [];\nfor (const source of sources) {\n  const file = join(MEDIA, \"words\", source.file);\n  if (!existsSync(file)) { console.warn(`No word timings at ${file}: transcribe it first (see the transcribe step).`); continue; }\n  for (const w of words(file)) {\n    if (!source.keep((w.s + w.e) / 2)) continue;\n    placed.push({ t: w.t, s: +source.at(w.s).toFixed(3), e: +source.at(w.e).toFixed(3) });\n  }\n}\nplaced.sort((a, b) => a.s - b.s);\n// A phrase ends at a sentence end or a breath longer than 0.45s.\nconst phrases = [];\nfor (const w of placed) {\n  const last = phrases.at(-1), prev = last?.words.at(-1);\n  if (!last || w.s - prev.e > 0.45 || /[.?!]$/.test(prev.t)) phrases.push({ s: w.s, e: w.e, words: [w] });\n  else { last.words.push(w); last.e = w.e; }\n}\nconst SPEECH = phrases.map((p) => ({ s: p.s, e: p.e, text: p.words.map((w) => w.t).join(\" \"), words: p.words }));\nwriteFileSync(join(ROOT, \"edit/speech.js\"), `// Written by scripts/speech.mjs from word timings. Do not edit by hand.\\nexport const SPEECH = ${JSON.stringify(SPEECH)};\\n`);\nfor (const p of SPEECH) console.log(`${p.s.toFixed(2)}-${p.e.toFixed(2)}  ${p.text}`);\nconsole.log(`${SPEECH.length} phrases written to edit/speech.js`);\n",
};
